export const databasesExercises: Exercise[] = [
  {"id":"db-ordre-des-colonnes-d-un-index-composite","type":"mcq","domain":"software","topic":"databases","difficulty":"senior","title":"Ordre des colonnes d'un index composite","company":"Markus Winand, « Use The Index, Luke », chap. « Concatenated Indexes »","question":"Une table `commandes(client_id, statut, date_creation)` porte un index composite `(statut, client_id)`. La requête récurrente est `WHERE client_id = ? AND statut = 'PAYE'` et l'appli exécute aussi souvent `WHERE client_id = ?` seul (sans statut). En supposant `client_id` très sélectif et `statut` peu sélectif (3 valeurs), quel est le principal défaut de cet index pour la charge décrite ?","options":["Le prédicat `WHERE client_id = ?` seul ne peut pas faire de recherche par arbre efficace car `client_id` n'est pas la colonne de tête, forçant un scan de tout l'index ou un seq scan","L'index est parfait car les deux prédicats de la première requête y figurent, l'ordre des colonnes n'affecte que la taille sur disque et jamais l'accès","L'index provoque systématiquement un tri supplémentaire sur `date_creation` puisque cette colonne absente empêche l'ordonnancement des feuilles","Le prédicat d'égalité sur `statut` en tête est optimal, mais l'optimiseur devra recharger chaque page deux fois faute de colonne couvrante"],"answer":0,"explanation":"Un index B-tree n'est efficacement utilisable en recherche par intervalle/égalité que sur un préfixe contigu de ses colonnes de tête. Avec `(statut, client_id)`, la requête `WHERE client_id = ?` seul ne fournit pas de prédicat sur la colonne de tête `statut` : l'arbre ne peut donc pas être parcouru par navigation (tree traversal), et le SGBD doit au mieux faire un full index scan, au pire un seq scan. Winand insiste : la colonne la plus fréquemment interrogée seule doit être en tête. Ici `(client_id, statut)` servirait les DEUX requêtes (l'index sur préfixe `client_id`). Placer `statut` (peu sélectif) en tête est le contre-exemple classique. Les distracteurs confondent : l'ordre affecte bien l'accès (2 est faux) ; il n'y a pas de tri forcé sur une colonne absente (3) ; le « double rechargement » décrit n'existe pas (4).","tags":["index-composite","b-tree","sélectivité","postgresql"]},
  {"id":"db-index-couvrant-et-visibility-map","type":"mcq","domain":"software","topic":"databases","difficulty":"senior","title":"Index couvrant et visibility map","company":"Documentation PostgreSQL, « Index-Only Scans and Covering Indexes »","question":"Vous créez `CREATE INDEX ON factures (client_id) INCLUDE (montant)` pour obtenir un index-only scan sur `SELECT montant FROM factures WHERE client_id = ?`. En production, `EXPLAIN` montre bien un « Index Only Scan » mais avec un grand nombre de « Heap Fetches ». Quelle est la cause la plus probable ?","options":["Les pages de la table ne sont pas marquées « all-visible » dans la visibility map, donc PostgreSQL doit consulter le heap pour vérifier la visibilité MVCC de chaque tuple","La clause INCLUDE ne stocke pas réellement `montant` dans les feuilles de l'index, ce qui oblige à un accès au heap pour lire la valeur incluse","Un index-only scan retourne toujours au heap quand la colonne du prédicat (`client_id`) n'est pas elle-même dans la clause INCLUDE","Le planificateur a choisi un index-only scan mais rebascule vers le heap car `montant` est de type numeric à longueur variable, non stockable en index"],"answer":0,"explanation":"Un index-only scan ne peut éviter le heap que si la page correspondante est marquée « all-visible » dans la visibility map (VM). Cette information de visibilité MVCC n'est PAS dans l'index ; elle est mise à jour par VACUUM. Sur une table à forte écriture, les pages fraîchement modifiées ne sont pas all-visible, donc PostgreSQL doit faire un « heap fetch » par tuple pour vérifier qu'il est visible pour la transaction courante — d'où le compteur Heap Fetches. Remède : VACUUM plus agressif. La clause INCLUDE stocke bien les valeurs dans les feuilles (distracteur 2 faux). La colonne du prédicat est de fait dans l'index (3 faux). numeric est parfaitement indexable (4 faux).","tags":["index-couvrant","index-only-scan","visibility-map","vacuum","mvcc"]},
  {"id":"db-b-tree-vs-lsm-amplification","type":"mcq","domain":"software","topic":"databases","difficulty":"senior","title":"B-tree vs LSM : amplification","company":"Kleppmann, DDIA, chap. 3, « SSTables and LSM-Trees / Comparing B-Trees and LSM-Trees »","question":"En comparant un moteur B-tree (ex. InnoDB) et un moteur LSM-tree (ex. RocksDB) pour une charge à forte écriture, laquelle de ces affirmations reflète correctement le compromis fondamental d'amplification ?","options":["Le LSM tend à offrir une meilleure amplification d'écriture (écritures séquentielles + compaction en lots) mais souffre d'une amplification de lecture supérieure car une clé peut résider dans plusieurs SSTables","Le B-tree a une meilleure amplification d'écriture car il réécrit une page entière à chaque modification, alors que le LSM réécrit inutilement toute la base à chaque compaction","Les deux ont une amplification d'écriture identique ; seule diffère l'amplification d'espace, systématiquement meilleure pour le B-tree grâce au fill factor","Le LSM élimine l'amplification de lecture grâce au WAL, tandis que le B-tree doit relire le journal de redo à chaque SELECT pour reconstruire la page"],"answer":0,"explanation":"Kleppmann : le LSM écrit de façon séquentielle et regroupe les écritures via la compaction, ce qui réduit généralement l'amplification d'écriture face au B-tree (qui doit écrire au moins la page + le WAL, soit ~2x, et fait des écritures aléatoires). En contrepartie, une lecture LSM peut devoir consulter la memtable + plusieurs SSTables de niveaux différents (d'où bloom filters pour limiter les accès), donnant une amplification de lecture plus élevée. Le distracteur 2 inverse le compromis. Le 3 est faux : les amplifications d'écriture diffèrent nettement. Le 4 confond WAL/redo avec le mécanisme de lecture.","tags":["lsm-tree","b-tree","amplification","rocksdb","ddia"]},
  {"id":"db-write-skew-et-serialisabilite","type":"mcq","domain":"software","topic":"databases","difficulty":"senior","title":"Write skew et sérialisabilité","company":"Kleppmann, DDIA, chap. 7, « Write Skew and Phantoms »","question":"Deux médecins de garde exécutent en parallèle, sous Snapshot Isolation (PostgreSQL REPEATABLE READ), la transaction : lire le nombre de médecins « on call », et si ≥ 2, se retirer de la garde. Chacun voit 2 médecins et se retire → 0 de garde. Quelle est la nature exacte de cette anomalie et le remède adéquat ?","options":["C'est un write skew : chaque transaction lit un ensemble puis écrit sur une ligne différente, sans conflit d'écriture direct ; il faut Serializable Snapshot Isolation (SERIALIZABLE) ou un verrou explicite (SELECT ... FOR UPDATE)","C'est un lost update classique : les deux transactions écrivent la même ligne ; l'activation de REPEATABLE READ suffit à le détecter automatiquement et à annuler l'une des deux","C'est un dirty read : une transaction lit une écriture non validée de l'autre ; passer en READ COMMITTED corrige l'invariant sans coût de sérialisation","C'est un phantom read pur : l'ajout d'un index sur la colonne « on call » force un range lock qui empêche l'insertion fantôme sous Snapshot Isolation"],"answer":0,"explanation":"Le write skew survient quand deux transactions lisent un même ensemble d'objets, prennent une décision sur cette lecture, puis modifient des objets DIFFÉRENTS. Sous SI, aucune n'entre en conflit d'écriture (elles touchent des lignes distinctes), donc SI ne détecte rien et l'invariant global (≥1 médecin de garde) est violé. Ce n'est pas un lost update (lignes différentes, donc le distracteur 2 est faux et REPEATABLE READ de Postgres ne l'annule pas). Ce n'est pas un dirty read (READ COMMITTED empêcherait encore moins, distracteur 3 faux). Remède : SERIALIZABLE (SSI détecte les dépendances rw) ou matérialiser le conflit via un verrou (FOR UPDATE) ou un verrou de prédicat.","tags":["write-skew","snapshot-isolation","serializable","acid","ddia"]},
  {"id":"db-lost-update-dans-une-transaction","type":"find-error","domain":"software","topic":"databases","difficulty":"senior","title":"Lost update dans une transaction","company":"Kleppmann, DDIA, chap. 7, « Preventing Lost Updates »","language":"sql","code":"-- Décrémenter le stock d'un produit lors d'une commande\nBEGIN;\n  SELECT quantite INTO @q FROM stock WHERE produit_id = 42;\n  -- logique applicative : if @q <= 0 then rollback\n  UPDATE stock\n     SET quantite = @q - 1\n   WHERE produit_id = 42;\nCOMMIT;","question":"Sous READ COMMITTED, deux exécutions concurrentes de ce bloc peuvent corrompre le stock. Quel est le bug précis et sa correction canonique ?","options":["C'est un lost update : la valeur lue dans @q devient périmée entre le SELECT et l'UPDATE ; il faut soit `UPDATE stock SET quantite = quantite - 1` (read-modify-write atomique), soit verrouiller via `SELECT ... FOR UPDATE`","Le bug est l'absence de COMMIT explicite après le SELECT ; sans point de sauvegarde intermédiaire, PostgreSQL relâche le verrou de lecture et l'UPDATE porte sur une version obsolète","Le problème est le niveau READ COMMITTED qui autorise les dirty reads ; passer en REPEATABLE READ suffit à sérialiser l'incrément sans changer la requête","Le bug est l'usage d'une variable de session @q non transactionnelle ; la stocker dans une table temporaire garantirait l'atomicité du read-modify-write"],"answer":0,"explanation":"Classique read-modify-write : T1 et T2 lisent tous deux quantite=10, chacun calcule 10-1 côté applicatif et écrit 9 ; une décrémentation est perdue (lost update). READ COMMITTED n'empêche pas cela car les deux UPDATE s'appliquent sur des lignes désormais validées. Corrections canoniques (Kleppmann) : (a) écriture atomique `SET quantite = quantite - 1` évaluée par le SGBD sous verrou de ligne ; (b) verrouillage explicite `SELECT ... FOR UPDATE` avant l'UPDATE ; (c) compare-and-set ; (d) détection auto sous SERIALIZABLE. READ COMMITTED n'autorise PAS les dirty reads (distracteur 3 faux). Le COMMIT manquant/variable de session ne sont pas la cause (les autres faux).","tags":["lost-update","read-committed","for-update","concurrence","sql"]},
  {"id":"db-mvcc-et-bloat-sous-postgresql","type":"mcq","domain":"software","topic":"databases","difficulty":"senior","title":"MVCC et bloat sous PostgreSQL","company":"Documentation PostgreSQL, « Concurrency Control / Routine Vacuuming »","question":"Une table PostgreSQL à fort taux d'UPDATE voit sa taille exploser et ses scans ralentir malgré peu de croissance de lignes « vivantes ». En quoi le mécanisme MVCC de PostgreSQL explique-t-il ce phénomène, et qu'est-ce qui l'atténue ?","options":["Chaque UPDATE crée une nouvelle version de ligne (tuple) et marque l'ancienne comme morte ; ces tuples morts occupent l'espace jusqu'au passage de VACUUM, et les updates HOT évitent d'en créer côté index quand aucune colonne indexée ne change","PostgreSQL modifie les tuples en place mais journalise l'ancienne image dans un rollback segment dédié ; le bloat vient du sous-dimensionnement de ce segment, corrigé en augmentant undo_tablespace","Le MVCC verrouille chaque ligne lue en écriture partagée, si bien que le bloat correspond aux entrées de la table de verrous ; réduire max_locks_per_transaction règle le problème","Les versions successives sont compressées dans le WAL uniquement ; le gonflement provient d'un checkpoint trop fréquent qui duplique les pages sales, atténué en allongeant checkpoint_timeout"],"answer":0,"explanation":"Le MVCC de PostgreSQL ne modifie pas les lignes en place : un UPDATE insère un nouveau tuple et marque l'ancien comme mort (dead tuple), visible tant que des snapshots peuvent en avoir besoin. Ces tuples morts gonflent la table (bloat) jusqu'à ce que VACUUM récupère l'espace ; d'où le ralentissement des seq scans. L'optimisation HOT (Heap-Only Tuple) permet, quand aucune colonne indexée n'est modifiée et qu'il y a de la place dans la page, de chaîner la nouvelle version SANS toucher les index, réduisant le bloat d'index. PostgreSQL n'utilise PAS de rollback/undo segment (contrairement à Oracle/MySQL InnoDB) — le distracteur 2 décrit un autre SGBD. Les 3 et 4 sont inventés.","tags":["mvcc","bloat","vacuum","hot-update","postgresql"]},
  {"id":"db-read-your-writes-apres-replication-async","type":"mcq","domain":"software","topic":"databases","difficulty":"senior","title":"Read-your-writes après réplication asynchrone","company":"Kleppmann, DDIA, chap. 5, « Reading Your Own Writes »","question":"Sur une architecture leader-follower avec réplication asynchrone et lecture répartie sur les followers, un utilisateur modifie son profil puis, en rechargeant, ne voit pas sa modification. Quelle stratégie garantit spécifiquement la cohérence « read-your-writes » sans imposer une lecture forte globale ?","options":["Router vers le leader (ou un follower suffisamment à jour via un timestamp logique) les seules lectures qui suivent une écriture récente du même utilisateur, pendant une fenêtre couvrant le lag de réplication","Passer toutes les lectures de tous les utilisateurs en quorum synchrone R=N pour éliminer le lag, ce qui est le seul moyen d'assurer read-your-writes sur du multi-follower","Activer la réplication semi-synchrone sur un follower unique, ce qui garantit que chaque utilisateur relit toujours ses écritures depuis n'importe quel réplica","Mettre en cache côté client la dernière écriture et l'afficher indéfiniment, en ignorant l'état des followers puisque la source de vérité applicative est le cache"],"answer":0,"explanation":"Read-your-writes (cohérence de session) exige seulement qu'un utilisateur voie SES propres écritures, pas une cohérence forte globale. Techniques (Kleppmann) : lire depuis le leader ce que l'utilisateur peut avoir modifié récemment ; suivre le timestamp/log position de la dernière écriture du client et router vers un follower ≥ ce point ; ou temporiser les lectures d'un client venant d'écrire. Le quorum R=N global (distracteur 2) est excessif et n'est pas « le seul moyen ». La semi-synchrone sur un follower ne garantit pas la lecture depuis n'importe quel réplica (3 faux). Le cache client indéfini casse la cohérence dès qu'un autre appareil écrit (4 faux).","tags":["read-your-writes","réplication","lag","cohérence-session","ddia"]},
  {"id":"db-quorum-r-w-n-n-implique-pas-la-linearisa","type":"mcq","domain":"software","topic":"databases","difficulty":"senior","title":"Quorum R+W>N n'implique pas la linéarisabilité","company":"Kleppmann, DDIA, chap. 5, « Limitations of Quorum Consistency »","question":"Un système Dynamo-style utilise N=3, W=2, R=2 (donc R+W>N). Un ingénieur affirme que cette condition garantit toujours de lire la dernière écriture validée. Pourquoi cette conclusion est-elle incorrecte ?","options":["R+W>N garantit seulement le chevauchement d'AU MOINS un nœud entre écriture et lecture, mais des écritures concurrentes, un sloppy quorum/hinted handoff, ou une écriture partiellement échouée peuvent renvoyer une valeur périmée","La condition est bien suffisante en théorie mais l'horloge murale des nœuds dérive, si bien que le versioning par timestamp choisit parfois la mauvaise valeur ; synchroniser via NTP restaure la garantie complète","L'erreur est arithmétique : il faut R+W≥2N pour un vrai chevauchement de quorum ; avec R+W>N le recouvrement peut être vide quand N est impair","La condition ne vaut que pour les lectures ; pour les écritures il faut W>N/2, donc W=2 avec N=3 crée un split-brain qui autorise deux leaders simultanés"],"answer":0,"explanation":"R+W>N assure que les ensembles de nœuds lus et écrits se chevauchent sur au moins un nœud — condition NÉCESSAIRE mais non SUFFISANTE pour lire la dernière valeur. Kleppmann liste les cas où l'on lit quand même du périmé : écritures concurrentes (il faut résoudre les conflits, ex. LWW/version vectors) ; sloppy quorum où les writes atterrissent sur des nœuds « de repli » ne recoupant pas le read quorum ; écriture qui réussit sur moins de W nœuds mais n'est pas annulée ; lecture concurrente d'une écriture en cours. L'arithmétique R+W>N est correcte (distracteur 3 faux). Ce n'est pas un problème d'horloge résolu par NTP (2 faux, le clock skew est un problème à part). Le 4 invente une contrainte.","tags":["quorum","dynamo","cohérence","sloppy-quorum","ddia"]},
  {"id":"db-resolution-de-conflits-en-multi-leader","type":"mcq","domain":"software","topic":"databases","difficulty":"senior","title":"Résolution de conflits en multi-leader","company":"Kleppmann, DDIA, chap. 5, « Handling Write Conflicts »","question":"Dans une réplication multi-leader (deux datacenters acceptant des écritures), on choisit « Last Write Wins » (LWW) basé sur un timestamp pour résoudre les conflits. Quel est le danger fondamental de LWW souvent sous-estimé ?","options":["LWW réalise la convergence en détruisant silencieusement des écritures : deux écritures concurrentes valides sont réputées ordonnées par horloge, donc l'une est écrasée et perdue sans trace, malgré un skew d'horloge qui rend l'ordre arbitraire","LWW empêche toute convergence car chaque leader garde sa version ; il faut nécessairement un arbitre central, ce qui contredit l'intérêt du multi-leader et impose de revenir au single-leader","LWW ne fonctionne qu'avec des horloges vectorielles ; sans elles, il déclenche une boucle de réplication infinie où chaque datacenter renvoie sans fin sa version à l'autre","LWW garantit qu'aucune donnée n'est perdue mais double le stockage car chaque valeur conserve toutes ses versions historiques jusqu'à une réconciliation manuelle par l'utilisateur"],"answer":0,"explanation":"LWW atteint la convergence (tous les réplicas finissent identiques) au prix de la durabilité : parmi des écritures concurrentes, celle au plus petit timestamp est purement et simplement écrasée et perdue, même si les deux étaient des succès validés côté client. Pire, avec un skew d'horloge, l'ordre imposé est arbitraire et peut faire « gagner » une écriture antérieure. Kleppmann décrit LWW comme convergent mais non « safe » (perte de données). Ce n'est pas une absence de convergence (distracteur 2). Les horloges vectorielles servent à DÉTECTER la concurrence, pas à faire fonctionner LWW (3 faux). LWW ne conserve pas l'historique (4 faux, c'est le rôle d'approches type siblings/CRDT).","tags":["multi-leader","lww","conflits","convergence","ddia"]},
  {"id":"db-hotspot-de-sharding-par-hash","type":"mcq","domain":"software","topic":"databases","difficulty":"senior","title":"Hotspot de sharding par hash","company":"Kleppmann, DDIA, chap. 6, « Partitioning of Key-Value Data / Skewed Workloads »","question":"Une plateforme partitionne les événements par `hash(user_id)` pour éviter les hotspots du partitionnement par plage. Un utilisateur « célébrité » génère soudain 90% du trafic d'écriture. Pourquoi le hash ne résout-il pas ce cas, et quelle mitigation s'applique ?","options":["Toutes les écritures d'un même user_id ont le même hash, donc tombent sur la même partition : le hash lisse la distribution des clés mais pas la charge d'une clé unique ; on ajoute un suffixe aléatoire à la clé chaude pour l'éparpiller, au prix de lectures fan-out","Le hash concentre par nature les clés proches sur une même partition, donc un utilisateur actif crée un point chaud ; il suffit de repasser au partitionnement par plage qui, lui, répartit toujours uniformément la charge","Le problème vient de la fonction de hachage non cryptographique ; utiliser SHA-256 au lieu de MurmurHash répartit les écritures d'un seul user_id sur les N partitions et supprime le hotspot","Un hotspot d'écriture sur une clé est impossible avec le hash car chaque écriture reçoit un hash différent grâce au salage temporel implicite ; le vrai souci est le rebalancing qui déplace la partition chaude"],"answer":0,"explanation":"Le partitionnement par hash répartit uniformément l'espace des CLÉS, mais toutes les opérations portant sur UNE MÊME clé (ici un user_id) aboutissent au même hash donc à la même partition : un seul acteur très actif crée un hotspot que le hash ne peut pas casser. Kleppmann : la mitigation consiste à ajouter au préfixe/suffixe de la clé chaude quelques bits aléatoires (split en sous-clés), ce qui répartit les écritures mais oblige les lectures à interroger toutes les sous-clés (fan-out) et à gérer le tracking des clés ainsi éclatées. Repasser au range (distracteur 2) n'aide pas et réintroduit d'autres hotspots. Changer de fonction de hash (3) ne change rien : même clé = même hash. Le 4 est faux, le hash n'introduit pas de salage temporel.","tags":["sharding","hotspot","hash-partitioning","clé-chaude","ddia"]},
  {"id":"db-rebalancing-et-hachage-coherent-le-piege","type":"mcq","domain":"software","topic":"databases","difficulty":"senior","title":"Rebalancing et hachage cohérent — le piège du modulo","company":"Kleppmann, DDIA, chap. 6, « Rebalancing Partitions »","question":"Un développeur assigne les clés aux nœuds via `hash(clé) mod N` où N = nombre de nœuds. Pourquoi cette approche est-elle catastrophique lors de l'ajout d'un nœud, et que recommande DDIA à la place ?","options":["Passer de N à N+1 change le résultat de `mod` pour la quasi-totalité des clés, forçant à déplacer presque toutes les données ; DDIA préconise un nombre fixe et élevé de partitions (bien > N nœuds) réassignées en bloc, ou le hachage cohérent","Le `mod N` provoque des collisions de hash dès que N dépasse 256, corrompant les clés ; DDIA recommande d'utiliser `hash(clé) AND (N-1)` qui évite les collisions en restant sur des puissances de deux","Le modulo répartit mal car il favorise les petits nœuds ; DDIA conseille de pondérer par la capacité via `hash(clé) mod (N * poids)` recalculé à chaque écriture pour garantir l'uniformité","Le problème est que `mod` n'est pas déterministe entre langages (signe des négatifs) ; normaliser avec `abs()` suffit à rendre le rebalancing incrémental sans déplacement massif de données"],"answer":0,"explanation":"Avec `hash(clé) mod N`, incrémenter N recalcule l'appartenance de presque toutes les clés (le reste modulo change pour la majorité), imposant un rebalancing massif — inacceptable. DDIA propose : (a) un nombre FIXE de partitions largement supérieur au nombre de nœuds, où l'ajout d'un nœud ne fait que lui transférer quelques partitions entières (approche de Riak/Elasticsearch) ; (b) le partitionnement dynamique (split/merge) ; ou le hachage cohérent (consistent hashing) qui limite le déplacement à ~K/N clés. Le distracteur 2 confond avec les collisions (faux). Le 3 invente une pondération. Le 4 mentionne un vrai piège (signe du modulo) mais qui n'est PAS le problème du rebalancing massif.","tags":["rebalancing","consistent-hashing","sharding","modulo","ddia"]},
  {"id":"db-dimensionnement-d-un-pool-de-connexions","type":"mcq","domain":"software","topic":"databases","difficulty":"senior","title":"Dimensionnement d'un pool de connexions","company":"Documentation PgBouncer & wiki PostgreSQL « Number Of Database Connections »","question":"Un service applicatif ouvre un pool de 400 connexions directes vers PostgreSQL (8 cœurs, disques SSD). Sous charge, le débit CHUTE alors que le CPU n'est pas saturé. Quel principe explique pourquoi un pool plus PETIT augmenterait le débit ?","options":["Au-delà d'un petit multiple du nombre de cœurs, ajouter des connexions actives crée de la contention (locks, context switches, cache CPU, I/O) : le débit total baisse ; la formule usuelle est ~ (2 × cœurs) + nombre de disques effectifs","Chaque connexion PostgreSQL consomme un thread noyau partagé ; 400 connexions dépassent le quota de threads, provoquant un thrashing mémoire résolu en augmentant simplement `max_connections` à 4000","Le débit chute car un pool trop grand désactive le cache de plan de requête partagé ; réduire le pool réactive `prepared_statements` global et double le throughput indépendamment du parallélisme","Un grand pool sature la bande passante réseau car chaque connexion émet des keepalive constants ; passer en UDP au lieu de TCP pour le protocole wire résout la contention sans toucher au pool"],"answer":0,"explanation":"Un serveur ne peut exécuter simultanément qu'un nombre limité de requêtes vraiment actives ; au-delà, les connexions supplémentaires se battent pour les mêmes ressources (verrous, contexte CPU, I/O), ajoutant du context switching et de la contention qui FONT BAISSER le débit total malgré un CPU apparemment non saturé (il attend sur des locks/I/O). Le wiki PostgreSQL propose l'heuristique `connexions ≈ (cœurs × 2) + nombre de broches disque`, d'où l'intérêt d'un pooler (PgBouncer) qui multiplexe des milliers de clients sur peu de connexions serveur. PostgreSQL utilise un PROCESSUS par connexion, pas un thread partagé (distracteur 2 faux). Les 3 et 4 sont inventés.","tags":["connection-pooling","dimensionnement","pgbouncer","throughput","postgresql"]},
  {"id":"db-pgbouncer-transaction-pooling-et-prepare","type":"mcq","domain":"software","topic":"databases","difficulty":"senior","title":"PgBouncer transaction pooling et prepared statements","company":"Documentation PgBouncer, « pool_mode » & « Feature limitations »","question":"Après migration de PgBouncer de `pool_mode = session` vers `pool_mode = transaction` pour absorber davantage de clients, l'application (utilisant des prepared statements côté serveur nommés) lève des erreurs « prepared statement \"S_1\" does not exist ». Pourquoi ?","options":["En mode transaction, une même connexion serveur est réattribuée à d'autres clients entre transactions ; un prepared statement préparé sur une connexion n'existe pas sur celle réattribuée ensuite au client, d'où l'erreur","Le mode transaction désactive le protocole étendu (extended query) au profit du simple query, ce qui interdit toute forme de requête paramétrée et force à concaténer les valeurs dans le SQL","Le mode transaction impose l'autocommit implicite, donc chaque `PREPARE` est immédiatement suivi d'un `DEALLOCATE ALL` automatique par PgBouncer pour libérer la mémoire du serveur","L'erreur vient du fait que le mode transaction chiffre les noms de statements par transaction ; il faut activer `server_reset_query = DISCARD ALL` pour restaurer les noms d'origine entre transactions"],"answer":0,"explanation":"En transaction pooling, PgBouncer n'associe une connexion serveur à un client que pour la DURÉE d'une transaction ; hors transaction, la connexion retourne au pool et peut servir un autre client. Un prepared statement serveur nommé est lié à UNE connexion serveur ; à la transaction suivante le client peut atterrir sur une autre connexion où ce statement n'a jamais été préparé → « does not exist ». Solutions : désactiver les server-side prepared statements côté driver, ou utiliser un PgBouncer récent avec support des prepared statements en transaction mode. Le mode transaction n'interdit pas le protocole étendu (distracteur 2 faux). Il n'y a pas de DEALLOCATE ALL auto par PREPARE (3 faux). Le 4 est inventé (DISCARD ALL nettoie justement les statements, il n'aide pas).","tags":["pgbouncer","transaction-pooling","prepared-statements","connection-pooling"]},
  {"id":"db-read-replicas-pour-absorber-les-connexio","type":"mcq","domain":"software","topic":"databases","difficulty":"senior","title":"Read replicas pour absorber les connexions","company":"Kleppmann, DDIA, chap. 5, « Setting Up New Followers » + doc PostgreSQL hot standby","question":"Pour absorber une explosion de connexions en lecture, on ajoute des read replicas et on y route les SELECT. Quel effet secondaire, propre à la nature asynchrone de la réplication, doit être anticipé dans la logique applicative ?","options":["Les lectures sur replica peuvent renvoyer des données périmées à cause du lag de réplication, cassant read-your-writes et la monotonicité ; il faut router certaines lectures vers le leader ou gérer explicitement la cohérence de session","Les read replicas partagent le pool de connexions du leader, donc router les lectures vers eux n'augmente pas la capacité totale de connexions du cluster tant qu'on n'active pas le multi-master","Chaque replica doit acquitter synchroniquement chaque commit du leader, si bien qu'ajouter des replicas augmente la latence d'écriture proportionnellement au nombre de replicas","Les SELECT sur replica acquièrent des verrous partagés propagés au leader, ce qui sérialise les écritures et supprime tout gain de scalabilité en lecture au-delà de deux replicas"],"answer":0,"explanation":"La réplication leader-follower usuelle est asynchrone : un replica accuse un retard (lag) sur le leader. Router les lectures vers les replicas augmente bien la capacité (chaque replica a son propre pool/CPU), mais une lecture peut voir un état antérieur — ce qui casse read-your-writes (l'utilisateur ne voit pas sa propre écriture récente) et la lecture monotone (retour en arrière apparent). Il faut donc gérer la cohérence de session (router vers le leader les lectures sensibles, suivre un log position, etc.). Le distracteur 2 est faux : les replicas ont leurs propres connexions. Le 3 décrit la réplication synchrone, pas le cas général. Le 4 invente une propagation de verrous inexistante.","tags":["read-replica","lag","cohérence","scalabilité-lecture","ddia"]},
  {"id":"db-fuite-de-connexions-du-pool","type":"find-error","domain":"software","topic":"databases","difficulty":"senior","title":"Fuite de connexions du pool","company":"CWE-772: Missing Release of Resource after Effective Lifetime","language":"java","code":"public User findUser(long id) throws SQLException {\n    Connection conn = dataSource.getConnection();\n    PreparedStatement ps = conn.prepareStatement(\n        \"SELECT id, name FROM users WHERE id = ?\");\n    ps.setLong(1, id);\n    ResultSet rs = ps.executeQuery();\n    if (rs.next()) {\n        return new User(rs.getLong(\"id\"), rs.getString(\"name\"));\n    }\n    conn.close();\n    return null;\n}","question":"Ce code provoque l'épuisement du pool de connexions en production. Quel est le défaut exact ?","options":["En cas de résultat trouvé (`rs.next()` vrai) la méthode `return` avant `conn.close()`, donc la connexion n'est jamais rendue au pool ; il faut un try-with-resources / bloc finally pour garantir la libération sur tous les chemins","Le bug est l'ouverture d'un PreparedStatement sans le fermer explicitement : les Connection sont bien libérées, mais le pool de statements se remplit et bloque au bout de N requêtes réussies","L'erreur est d'appeler `getConnection()` hors d'une transaction ; sans `setAutoCommit(false)`, la connexion reste marquée active côté serveur et n'est jamais éligible au recyclage par le pool","Le défaut est le `return null` final qui laisse le garbage collector fermer la connexion de façon non déterministe ; remplacer par `conn.close(); return Optional.empty();` corrige la fuite"],"answer":0,"explanation":"Le chemin nominal — utilisateur trouvé — exécute `return new User(...)` AVANT d'atteindre `conn.close()`. La connexion n'est donc jamais restituée au pool sur le cas le plus fréquent ; sous charge le pool s'épuise et les getConnection() bloquent/expirent. Correction canonique : try-with-resources sur Connection/PreparedStatement/ResultSet (ou un bloc finally) pour garantir la fermeture sur TOUS les chemins, y compris exception. Le statement non fermé aggrave mais n'est pas la cause première de l'épuisement des connexions (distracteur 2). L'autocommit n'est pas en cause (3). Compter sur le GC est effectivement mauvais, mais le vrai bug est le chemin de retour qui saute close() — le 4 le décrit mal (le return null atteint close()).","tags":["connection-leak","pool","try-with-resources","cwe-772","java"]},
  {"id":"db-n-1-masque-par-un-orm","type":"find-error","domain":"software","topic":"databases","difficulty":"senior","title":"N+1 masqué par un ORM","company":"Kleppmann, DDIA, chap. 2 (accès relationnel) — anti-pattern N+1 (doc ORM)","language":"python","code":"# SQLAlchemy — afficher chaque commande et le nom de son client\ncommandes = session.query(Commande).all()\nfor c in commandes:\n    # relation Commande.client (lazy='select' par défaut)\n    print(c.id, c.client.nom)\n\n# Modèles :\n# class Commande(Base):\n#   client_id = Column(ForeignKey('clients.id'))\n#   client = relationship('Client')  # lazy par défaut","question":"Cette boucle est correcte fonctionnellement mais s'écroule sur 10 000 commandes. Quel est le problème et sa correction idiomatique ?","options":["C'est le problème N+1 : 1 requête charge les commandes puis chaque accès à `c.client` déclenche 1 SELECT (lazy loading), soit N requêtes supplémentaires ; il faut un chargement anticipé (`joinedload`/`selectinload`) ou un JOIN explicite","Le bug est l'appel à `.all()` qui charge tout en mémoire ; remplacer par `.yield_per(100)` supprime à lui seul les requêtes redondantes en streamant les jointures côté serveur","Le problème est l'absence d'index sur `clients.id` ; comme c'est une clé primaire déjà indexée, la solution réelle est d'ajouter un index sur `commandes.client_id` pour transformer les N SELECT en un seul index scan","Le défaut est le lazy loading qui ouvre N connexions distinctes du pool en parallèle ; configurer `lazy='dynamic'` réutilise une connexion unique et résout le goulot d'étranglement"],"answer":0,"explanation":"Anti-pattern N+1 : une requête ramène les N commandes, puis chaque accès à la relation lazy `c.client` émet un SELECT séparé → 1 + N requêtes, chacune avec son aller-retour réseau, ce qui écroule la latence à grande échelle. Correction idiomatique : eager loading via `joinedload` (JOIN unique) ou `selectinload` (2 requêtes, IN sur les ids), ou un JOIN explicite dans la requête. `yield_per` ne change pas le nombre de requêtes relationnelles (distracteur 2 faux). L'index sur client_id n'attaque pas la cause : le problème est le NOMBRE de round-trips, pas la vitesse d'un lookup indexé sur une PK (3 faux). `lazy='dynamic'` renvoie une requête, il n'agrège pas (4 faux).","tags":["n+1","orm","eager-loading","sqlalchemy","python"]},
  {"id":"db-predicat-qui-empeche-l-usage-de-l-index","type":"find-error","domain":"software","topic":"databases","difficulty":"senior","title":"Prédicat qui empêche l'usage de l'index","company":"Markus Winand, « Use The Index, Luke », chap. « Functions / Case-Insensitive Search »","language":"sql","code":"SELECT id, nom\n  FROM utilisateurs\n WHERE LOWER(email) = 'alice@example.com';","question":"L'index `CREATE INDEX idx_email ON utilisateurs (email);` existe, mais la requête suivante fait un seq scan sur des millions de lignes. Pourquoi, et quelle est la correction ?","options":["`LOWER(email)` applique une fonction sur la colonne indexée : l'index sur `email` ne peut pas servir un prédicat sur `LOWER(email)` ; il faut un index fonctionnel `CREATE INDEX ON utilisateurs (LOWER(email))` (ou une colonne citext)","Le seq scan vient du `=` sur une colonne texte non collationnée ; ajouter `COLLATE \"C\"` à la requête force l'optimiseur à réutiliser l'index B-tree existant sans le recréer","L'index n'est pas utilisé car `LOWER()` retourne un type différent ; caster explicitement en `::text` dans la requête réaligne les types et permet à l'index standard d'être choisi","Le problème est l'absence de statistiques à jour ; lancer `ANALYZE utilisateurs` suffit à faire préférer l'index sur `email` malgré la fonction appliquée dans le WHERE"],"answer":0,"explanation":"Un index B-tree ordinaire sur `email` stocke les valeurs BRUTES de `email`. Le prédicat porte sur `LOWER(email)`, une expression dérivée que l'index ne connaît pas : l'optimiseur ne peut pas s'en servir et retombe sur un seq scan (Winand : « appliquer une fonction sur une colonne indexée désactive l'index »). Correction : créer un index d'expression `CREATE INDEX ON utilisateurs (LOWER(email))`, indexer directement l'expression utilisée, ou utiliser un type insensible à la casse (citext). Un COLLATE (distracteur 2) ne change pas le fait que LOWER() est appliqué. Le cast ::text (3) est hors sujet. ANALYZE (4) ne rend pas l'index utilisable pour une expression qu'il n'indexe pas.","tags":["index-fonctionnel","seq-scan","use-the-index-luke","sargable","sql"]},
  {"id":"db-cast-implicite-qui-tue-l-index","type":"find-error","domain":"software","topic":"databases","difficulty":"senior","title":"Cast implicite qui tue l'index","company":"Documentation PostgreSQL, « Index Types / Operator Classes » ; Winand « Use The Index, Luke »","language":"sql","code":"SELECT * FROM commandes\n WHERE numero_client = 100425;   -- numero_client est varchar","question":"La colonne `numero_client` est de type `varchar` et porte un index B-tree. La requête ci-dessous n'utilise pas l'index. Quelle est la cause précise ?","options":["Comparer un `varchar` à un littéral numérique force PostgreSQL à caster la colonne en un type numérique côté gauche, rendant l'expression non-sargable ; il faut comparer à une chaîne : `WHERE numero_client = '100425'`","PostgreSQL refuse d'utiliser un index B-tree sur varchar dès qu'un entier apparaît dans le WHERE car les classes d'opérateurs texte et entier sont incompatibles ; recréer l'index avec `USING hash` résout le typage","Le littéral entier déclenche un tri implicite de l'index en ordre numérique incompatible avec l'ordre lexicographique des feuilles ; désactiver `enable_seqscan` force le bon plan sans changer la requête","Le cast se fait côté littéral (entier vers texte) donc l'index reste utilisable ; le vrai problème est l'absence de `VACUUM ANALYZE`, seul capable de recalculer la sélectivité d'une colonne varchar"],"answer":0,"explanation":"Quand on compare une colonne `varchar` à un littéral entier, PostgreSQL doit réconcilier les types. La règle de résolution ici convertit la COLONNE (côté texte) pour la comparaison numérique implicite, transformant le prédicat en quelque chose comme `numero_client::numeric = 100425` : une fonction/cast est appliquée à la colonne, l'index texte devient inutilisable (non-sargable) → seq scan. Correction : passer un littéral du même type, `= '100425'`, pour que la comparaison porte sur la colonne brute indexée. Les classes d'opérateurs ne sont pas « incompatibles » au point d'exiger un index hash (distracteur 2). Il n'y a pas de tri implicite forcé (3). Le cast ne se fait pas forcément côté littéral, et ANALYZE ne corrige pas ce blocage (4).","tags":["cast-implicite","sargable","index","type-varchar","sql"]},
  {"id":"db-left-join-annule-par-le-where","type":"find-error","domain":"software","topic":"databases","difficulty":"senior","title":"LEFT JOIN annulé par le WHERE","company":"Documentation PostgreSQL, « Joined Tables » (comportement des outer joins et prédicats)","language":"sql","code":"SELECT cl.id, cl.nom, co.id AS commande_id\n  FROM clients cl\n  LEFT JOIN commandes co ON co.client_id = cl.id\n WHERE co.date >= '2026-01-01';","question":"On veut lister TOUS les clients avec, le cas échéant, leurs commandes de 2026. Cette requête n'affiche jamais les clients sans commande 2026. Quel est le bug ?","options":["Le prédicat `co.date >= '2026-01-01'` est dans le WHERE : il élimine les lignes où `co.*` est NULL (clients sans commande), transformant le LEFT JOIN en INNER JOIN de fait ; il faut déplacer la condition dans le `ON`","Le bug est l'ordre des tables : PostgreSQL fait un LEFT JOIN depuis la table de droite ; inverser en `commandes LEFT JOIN clients` restaure l'inclusion de tous les clients sans toucher au WHERE","Le problème vient du format de date littéral ambigu ; caster en `DATE '2026-01-01'` change la sémantique du LEFT JOIN et réintègre les clients sans commande de 2026","L'erreur est l'absence de `COALESCE(co.date, '2026-01-01')` dans le WHERE ; sans elle, la comparaison sur NULL renvoie FALSE et exclut à tort les clients appariés mais hors 2026"],"answer":0,"explanation":"Dans un LEFT JOIN, les clients sans commande appariée produisent des colonnes `co.*` à NULL. Or `co.date >= '2026-01-01'` évalué dans le WHERE sur un NULL donne UNKNOWN (donc la ligne est écartée) : le WHERE filtre APRÈS la jointure et supprime toutes les lignes non appariées, ce qui dégrade le LEFT JOIN en INNER JOIN. Correction : déplacer la condition de filtrage dans le `ON` (`LEFT JOIN commandes co ON co.client_id = cl.id AND co.date >= '2026-01-01'`), pour qu'elle restreigne l'appariement sans éliminer les clients non appariés. Inverser les tables (distracteur 2) ne corrige rien. Le format de date (3) n'a aucun effet sémantique ici. Le COALESCE (4) est un contournement fragile et incorrect.","tags":["left-join","null","predicate-pushdown","outer-join","sql"]},
  {"id":"db-not-in-et-la-trappe-des-null","type":"find-error","domain":"software","topic":"databases","difficulty":"senior","title":"NOT IN et la trappe des NULL","company":"Documentation PostgreSQL, « Subquery Expressions / NOT IN » ; trois valeurs logiques","language":"sql","code":"SELECT p.id, p.nom\n  FROM produits p\n WHERE p.id NOT IN (SELECT produit_id FROM commandes);","question":"Cette requête censée trouver les produits jamais commandés renvoie parfois zéro ligne alors que de tels produits existent. Quel est le piège ?","options":["Si `commandes.produit_id` contient au moins un NULL, `NOT IN` renvoie UNKNOWN pour toutes les lignes (jamais TRUE), donc aucun résultat ; il faut `NOT EXISTS` ou filtrer les NULL de la sous-requête","Le bug est que `NOT IN` matérialise toute la sous-requête en mémoire et déborde silencieusement au-delà de work_mem, tronquant le résultat ; remplacer par `<> ALL` corrige la limite mémoire","Le problème est l'absence de `DISTINCT` dans la sous-requête : les doublons de `produit_id` font échouer la comparaison ensembliste de `NOT IN` sur les identifiants répétés","L'erreur vient du type de `id` (bigint) comparé à `produit_id` (integer) : `NOT IN` applique un cast lossy qui exclut à tort les identifiants supérieurs à 2^31"],"answer":0,"explanation":"Piège classique de la logique ternaire SQL : `x NOT IN (liste contenant NULL)` s'évalue en `x <> a AND x <> b AND x <> NULL ...`. Dès qu'un NULL est présent, `x <> NULL` vaut UNKNOWN, la conjonction ne peut jamais valoir TRUE, et AUCUNE ligne n'est retournée — même pour des produits réellement absents. Si `produit_id` est nullable (commandes sans produit), la requête casse silencieusement. Corrections : `NOT EXISTS (SELECT 1 FROM commandes c WHERE c.produit_id = p.id)` (sémantique correcte et souvent plus efficace), ou `NOT IN (SELECT produit_id FROM commandes WHERE produit_id IS NOT NULL)`. Les distracteurs 2/3/4 inventent des causes (mémoire, doublons, cast) qui ne produisent pas ce comportement.","tags":["not-in","null","logique-ternaire","not-exists","sql"]},
  {"id":"db-group-by-et-colonnes-non-agregees","type":"find-error","domain":"software","topic":"databases","difficulty":"senior","title":"GROUP BY et colonnes non agrégées","company":"Documentation PostgreSQL, « SELECT / GROUP BY » ; norme SQL functional dependency","language":"sql","code":"SELECT pays, nom_client, COUNT(*)\n  FROM clients\n GROUP BY pays;","question":"Portée depuis MySQL (mode non strict) vers PostgreSQL, cette requête échoue avec « column must appear in the GROUP BY clause or be used in an aggregate function ». Que révèle réellement cette erreur sur la requête d'origine ?","options":["`nom_client` n'est pas fonctionnellement déterminé par la clé de groupe (on groupe sur `pays`) : sous MySQL laxiste, une valeur arbitraire par groupe était renvoyée en silence, masquant un résultat non déterministe","L'erreur est purement syntaxique : PostgreSQL exige les colonnes du SELECT dans le même ordre que le GROUP BY ; réordonner `GROUP BY nom_client, pays` compile sans changer la sémantique","PostgreSQL n'autorise le GROUP BY que sur des colonnes indexées ; il faut créer un index sur `pays` pour que l'agrégat `COUNT(*)` accepte `nom_client` dans la projection","Le problème est l'agrégat `COUNT(*)` qui doit être `COUNT(nom_client)` pour lier la colonne au groupe ; ce simple changement rend `nom_client` légal dans le SELECT"],"answer":0,"explanation":"En groupant sur `pays`, chaque groupe agrège potentiellement plusieurs clients de noms différents : `nom_client` n'est pas fonctionnellement déterminé par la clé de groupe, donc PostgreSQL (conforme à la norme) refuse de le projeter. MySQL en mode `ONLY_FULL_GROUP_BY` désactivé acceptait la requête et renvoyait une valeur ARBITRAIRE de `nom_client` par pays — un résultat non déterministe silencieux, souvent un vrai bug métier masqué. L'erreur de PostgreSQL révèle donc une ambiguïté sémantique, pas un détail de syntaxe (distracteur 2 faux). Le GROUP BY n'exige pas d'index (3 faux). Changer COUNT(*) en COUNT(nom_client) ne lie pas la colonne au groupe (4 faux).","tags":["group-by","functional-dependency","mysql-vs-postgres","non-déterminisme","sql"]},
  {"id":"db-index-partiel-quand-l-utiliser","type":"mcq","domain":"software","topic":"databases","difficulty":"senior","title":"Index partiel : quand l'utiliser","company":"Documentation PostgreSQL, « Partial Indexes »","question":"Sur une table `jobs(statut, ...)` de 500M lignes dont seulement 0,1% ont `statut = 'PENDING'`, la file de traitement fait sans cesse `WHERE statut = 'PENDING' ORDER BY cree_le`. Quel index partiel est le plus pertinent, et quel bénéfice concret par rapport à un index complet ?","options":["`CREATE INDEX ON jobs (cree_le) WHERE statut = 'PENDING'` : l'index ne contient que les ~0,1% de lignes pertinentes, restant minuscule et chaud en cache, et les lignes passant à un autre statut sortent de l'index","`CREATE INDEX ON jobs (statut, cree_le)` complet est équivalent en taille à l'index partiel car PostgreSQL compresse les valeurs répétées de `statut` ; le partiel n'apporte qu'une lisibilité de code","`CREATE INDEX ON jobs (statut) INCLUDE (cree_le) WHERE statut IS NOT NULL` : la clause INCLUDE remplace le prédicat partiel et couvre mieux le tri sur `cree_le` que le WHERE","`CREATE UNIQUE INDEX ON jobs (cree_le) WHERE statut = 'PENDING'` : l'unicité partielle est requise pour que PostgreSQL puisse restreindre l'index aux lignes PENDING, sinon le prédicat est ignoré"],"answer":0,"explanation":"Un index partiel n'indexe que les lignes vérifiant le prédicat. Ici la file ne s'intéresse qu'aux jobs PENDING (0,1%) : `CREATE INDEX ON jobs (cree_le) WHERE statut = 'PENDING'` produit un index minuscule (~500k entrées au lieu de 500M), qui tient en cache, s'ordonne directement sur `cree_le` (servant l'ORDER BY), et se vide automatiquement quand un job change de statut (l'entrée quitte l'index). Bénéfices : taille, cache, coût de maintenance réduit. L'index complet (distracteur 2) est bien plus gros et la « compression » invoquée ne change pas le nombre d'entrées. Le 3 confond INCLUDE et prédicat partiel. Le 4 est faux : l'unicité n'est pas nécessaire pour un index partiel.","tags":["index-partiel","file-attente","sélectivité","postgresql"]},
  {"id":"db-diagnostic-explain-seq-scan-vs-index-sca","type":"mcq","domain":"software","topic":"databases","difficulty":"senior","title":"Diagnostic EXPLAIN : seq scan vs index scan","company":"Documentation PostgreSQL, « Using EXPLAIN » ; Winand « Use The Index, Luke »","question":"`EXPLAIN` choisit un Seq Scan alors qu'un index existe sur la colonne du WHERE, et la requête ramène 40% des lignes. Pourquoi ce choix est-il souvent CORRECT et non un bug de l'optimiseur ?","options":["Un index scan implique un accès aléatoire au heap par ligne (random I/O) ; au-delà d'un certain pourcentage de lignes lues, le seq scan (I/O séquentiel, préfetch) devient moins coûteux, donc l'optimiseur le préfère à raison","Le seq scan est toujours choisi quand la table dépasse shared_buffers car l'index ne tiendrait plus en cache ; réduire la taille de la table via partitionnement rétablirait automatiquement l'index scan","L'optimiseur ignore l'index parce qu'il ne peut estimer la sélectivité sans un index BRIN ; convertir l'index B-tree en BRIN lui fournit les bornes nécessaires pour préférer l'index scan","À 40% de lignes, PostgreSQL bascule en Bitmap Heap Scan qui est un cas dégénéré de seq scan ; forcer `SET enable_bitmapscan = off` restaure un vrai index scan plus rapide"],"answer":0,"explanation":"Lire une ligne via un index secondaire impose de sauter au heap à un emplacement quasi aléatoire (random_page_cost). Quand la requête sélectionne une grande fraction de la table (ici 40%), le nombre d'accès aléatoires devient tel qu'un Seq Scan — lecture séquentielle avec préfetch et faible coût par page (seq_page_cost) — est réellement moins cher. L'optimiseur, via ses statistiques de sélectivité et son modèle de coût, fait donc le bon choix : un index n'est avantageux que pour des prédicats sélectifs (Winand : « an index is only useful for a small fraction of rows »). Les distracteurs 2/3/4 invoquent des règles inexistantes (shared_buffers, BRIN, bitmap) ; forcer l'index scan ici DÉGRADERAIT la performance.","tags":["explain","seq-scan","sélectivité","random-io","postgresql"]},
  {"id":"db-cap-mal-compris-le-c-n-est-pas-acid","type":"mcq","domain":"software","topic":"databases","difficulty":"senior","title":"CAP mal compris : le C n'est pas ACID","company":"Kleppmann, DDIA, chap. 9, « The Unhelpful CAP Theorem »","question":"Un architecte affirme : « notre base est CP donc elle garantit l'ACID et la cohérence forte en toutes circonstances ». Où se trompe-t-il sur la sémantique exacte du théorème CAP ?","options":["Le « C » de CAP désigne la linéarisabilité (un modèle de cohérence précis), pas la cohérence ACID ; et CAP ne parle QUE du comportement pendant une partition réseau, pas des compromis latence/cohérence en fonctionnement normal","Le « C » de CAP est bien la cohérence transactionnelle ACID ; l'erreur est de croire qu'un système CP reste disponible pendant une partition, alors qu'il sacrifie la cohérence et non la disponibilité","CAP impose de choisir exactement deux propriétés sur trois en permanence ; un système CP renonce donc à la Partition-tolerance, ce qui le rend inutilisable dès qu'un câble réseau tombe","Le théorème garantit qu'un système AP offre toujours la linéarisabilité tant qu'il n'y a pas de partition, si bien que CP et AP sont équivalents hors panne ; la nuance ACID est secondaire"],"answer":0,"explanation":"Kleppmann critique la formulation populaire de CAP. Précisions exactes : (1) le « C » est la LINÉARISABILITÉ, un modèle de cohérence spécifique, PAS la cohérence ACID (le C d'ACID est autre chose — le respect des invariants). (2) CAP ne dit rien du comportement hors partition ; il oppose seulement, PENDANT une partition, disponibilité et linéarisabilité. Dire « CP donc ACID en toutes circonstances » confond deux notions et étend abusivement le théorème au fonctionnement normal (c'est PACELC qui couvre le compromis latence/cohérence hors panne). Le distracteur 2 réassigne mal C↔A. Le 3 déforme la P (on ne « renonce » pas à la tolérance aux partitions, elles arrivent). Le 4 est faux.","tags":["cap","linéarisabilité","acid","pacelc","ddia"]},
  {"id":"db-pacelc-au-dela-de-cap","type":"mcq","domain":"software","topic":"databases","difficulty":"senior","title":"PACELC : au-delà de CAP","company":"Abadi, « Consistency Tradeoffs in Modern Distributed Database System Design » (PACELC) ; DDIA chap. 9","question":"PACELC étend CAP. Quelle formulation décrit correctement ce qu'il ajoute et ce qu'un système « PC/EL » signifie ?","options":["En cas de Partition (P), on arbitre Availability vs Consistency ; Else (E, fonctionnement normal), on arbitre Latency vs Consistency. « PC/EL » = privilégie la cohérence en partition, mais privilégie la latence (au détriment de la cohérence) le reste du temps","PACELC ajoute la Persistence : en Partition on choisit Availability vs Consistency, sinon (E) on choisit Endurance vs Latency ; « PC/EL » signifie cohérent en panne et endurant en régime normal","PACELC remplace CAP par un choix binaire Latency/Consistency valable uniquement pendant les partitions ; « PC/EL » décrit un système qui reste cohérent partout, la lettre E n'ayant qu'un rôle mnémotechnique","PACELC formalise que tout système doit choisir Partition-tolerance ; « PC/EL » indique qu'en cas de panne il devient partition-tolérant et qu'en temps normal il élimine la latence par du cache local fort"],"answer":0,"explanation":"PACELC (Abadi) : IF Partition, alors compromis Availability/Consistency (comme CAP) ; ELSE (fonctionnement normal, sans partition), compromis Latency/Consistency. Son apport clé sur CAP est justement de reconnaître qu'un compromis existe MÊME sans panne : offrir une cohérence forte (linéarisable) coûte de la latence (coordination). Un système « PC/EL » choisit la Cohérence pendant une partition et la Latence (donc cohérence relâchée) en régime normal. Les distracteurs réinventent les lettres (Persistence/Endurance : faux) ou restreignent PACELC aux seules partitions (faux, tout son intérêt est le « Else »).","tags":["pacelc","cap","latence","cohérence","systèmes-distribués"]},
  {"id":"db-pattern-outbox-et-double-ecriture","type":"mcq","domain":"software","topic":"databases","difficulty":"senior","title":"Pattern Outbox et double écriture","company":"Kleppmann, DDIA, chap. 11 (CDC) ; pattern Transactional Outbox","question":"Un service doit, à chaque commande créée, persister la commande ET publier un événement sur Kafka. Écrire en base puis publier dans Kafka en deux étapes est risqué. Quel problème le pattern Outbox résout-il, et comment ?","options":["Il élimine le dual-write : l'événement est inséré dans une table `outbox` DANS la même transaction que la commande (atomicité locale), puis un relais (CDC/poller) lit l'outbox et publie sur Kafka, garantissant l'at-least-once cohérent","Il garantit l'exactly-once distribué en verrouillant Kafka et la base dans une transaction XA à deux phases ; l'outbox n'est qu'un journal de compensation utilisé si le commit 2PC échoue","Il évite le N+1 d'événements en agrégeant toutes les publications d'une requête HTTP dans un seul message ; la table outbox sert de tampon de batch vidé à la fin de la requête","Il résout le lag de réplication en écrivant l'événement directement sur le follower Kafka le plus proche, contournant le leader de la base pour réduire la latence de publication"],"answer":0,"explanation":"Le danger du « dual write » : si l'on écrit la commande en base puis, séparément, on publie sur Kafka, un crash entre les deux laisse un état incohérent (commande sans événement, ou l'inverse) — il n'y a pas d'atomicité entre deux systèmes hétérogènes. Le pattern Transactional Outbox insère l'événement dans une table `outbox` DANS LA MÊME transaction de base que la commande : l'atomicité locale garantit qu'ils sont commités ensemble. Un processus relais (poller ou CDC lisant le WAL, ex. Debezium) lit ensuite l'outbox et publie sur Kafka de façon fiable (at-least-once, idempotence côté consommateur). Le 2PC/XA (distracteur 2) est justement ce qu'on veut éviter. Les 3 et 4 sont hors sujet.","tags":["outbox","cdc","dual-write","kafka","ddia"]},
  {"id":"db-cdc-base-sur-le-log-vs-triggers","type":"mcq","domain":"software","topic":"databases","difficulty":"senior","title":"CDC basé sur le log vs triggers","company":"Kleppmann, DDIA, chap. 11, « Change Data Capture »","question":"Pour alimenter un index de recherche depuis PostgreSQL, on hésite entre du CDC par lecture du WAL (logical decoding / Debezium) et du CDC applicatif par triggers écrivant dans une table de log. Quel avantage décisif a l'approche par log de réplication ?","options":["Le log (WAL) est la source de vérité ordonnée de TOUTES les modifications validées : le lire capture chaque changement dans l'ordre exact des commits, sans surcoût par écriture ni risque d'oublier un chemin d'écriture, contrairement aux triggers","Les triggers sont plus fiables car exécutés en synchrone dans la transaction, alors que le WAL peut perdre des changements lors d'un checkpoint ; le seul intérêt du log est d'éviter d'écrire du code SQL","Le CDC par log ne fonctionne qu'en append-only et ne capture pas les UPDATE/DELETE, tandis que les triggers les capturent tous ; on choisit le log uniquement pour les tables immuables","Le WAL n'expose que les identifiants de pages physiques, pas les valeurs de colonnes ; le décodage logique est donc impossible et l'on est contraint aux triggers pour obtenir les nouvelles valeurs de lignes"],"answer":0,"explanation":"Le WAL/redo log est le journal ordonné et durable de toutes les modifications validées : c'est déjà la source de vérité que la réplication utilise. Le CDC par décodage logique (logical decoding, Debezium) lit ce log et obtient donc, dans l'ordre exact des commits, INSERT/UPDATE/DELETE de toutes les transactions, sans ajouter d'écritures par ligne ni dépendre de la discipline applicative (un trigger oublié = changements perdus). Les triggers, eux, alourdissent chaque écriture, s'exécutent dans la transaction (surcoût de latence) et doivent couvrir tous les chemins. Le distracteur 2 inverse la fiabilité (le WAL ne perd pas de commits validés). Le décodage logique capture bien UPDATE/DELETE (3 faux) et expose les valeurs de colonnes via le plugin de décodage (4 faux).","tags":["cdc","wal","logical-decoding","debezium","ddia"]},
  {"id":"db-denormalisation-quel-cout-accepter","type":"mcq","domain":"software","topic":"databases","difficulty":"senior","title":"Dénormalisation : quel coût accepter","company":"Kleppmann, DDIA, chap. 1 & 3 ; principes de normalisation","question":"On dénormalise en copiant le `nom_auteur` dans chaque ligne `article` pour éviter une jointure fréquente. Quel est le compromis fondamental exact introduit, et quand est-il justifié ?","options":["On accélère les lectures (plus de jointure) mais on introduit une redondance : chaque changement de nom d'auteur doit être propagé à toutes les copies, avec risque d'incohérence si la mise à jour n'est pas atomique ; justifié quand les lectures dominent massivement","On réduit l'espace disque en supprimant la table auteurs, au prix d'une écriture plus lente ; justifié uniquement lorsque le taux d'écriture dépasse le taux de lecture d'un facteur dix","On élimine tout risque d'anomalie de mise à jour car la donnée devient locale à chaque ligne ; c'est toujours préférable dès qu'une table dépasse le million de lignes","On transforme une relation many-to-one en many-to-many, ce qui supprime les verrous de clé étrangère ; justifié seulement en base document, jamais en relationnel"],"answer":0,"explanation":"La normalisation stocke chaque fait UNE fois (source unique de vérité), au prix de jointures en lecture. La dénormalisation duplique la donnée pour éviter la jointure : lectures plus rapides, MAIS redondance à maintenir — tout changement du nom d'auteur doit être répercuté sur toutes les copies, avec risque d'incohérence (anomalie de mise à jour) si ce n'est pas fait atomiquement/exhaustivement. C'est donc un arbitrage lecture vs coût d'écriture/cohérence, justifié quand les lectures dominent très largement et que les écritures de la donnée dupliquée sont rares. Le distracteur 2 se trompe sur le gain (ce n'est pas l'espace, c'est souvent l'inverse) et le seuil. Le 3 est faux (elle CRÉE des anomalies de mise à jour). Le 4 est un contresens.","tags":["dénormalisation","normalisation","redondance","cohérence","ddia"]},
  {"id":"db-modele-graphe-vs-relationnel-pour-les-re","type":"mcq","domain":"software","topic":"databases","difficulty":"senior","title":"Modèle graphe vs relationnel pour les relations profondes","company":"Kleppmann, DDIA, chap. 2, « Graph-Like Data Models »","question":"Pour une requête de type « trouve tous les descendants d'un nœud à profondeur variable » (parcours transitif), pourquoi un modèle/moteur graphe est-il souvent supérieur à un schéma relationnel classique ?","options":["Le parcours transitif à profondeur inconnue s'exprime mal en SQL (jointures récursives coûteuses, nombre de JOINs non borné à l'avance) alors qu'un moteur graphe traverse les arêtes en suivant des pointeurs, à coût proportionnel au sous-graphe visité","Un moteur graphe stocke toutes les arêtes dans un seul index B-tree trié, ce qui rend chaque parcours O(1) quelle que soit la profondeur, là où le relationnel est intrinsèquement O(n²)","Le relationnel ne peut pas modéliser de relations many-to-many, obligatoires pour un graphe ; le modèle graphe les autorise, ce qui est l'unique raison de sa supériorité en parcours","Les bases graphes garantissent la linéarisabilité des parcours grâce à un verrou global sur le graphe, éliminant les phantom reads que le relationnel subit lors d'un parcours multi-niveaux"],"answer":0,"explanation":"Kleppmann : les modèles graphe brillent quand les données sont fortement interconnectées et que les requêtes traversent un nombre VARIABLE/inconnu d'arêtes (ex. amis d'amis, descendants). En SQL, cela exige des CTE récursives ou un nombre de JOINs qu'on ne connaît pas à l'écriture — verbeux et souvent coûteux. Un moteur graphe suit les arêtes comme des pointeurs, avec un coût proportionnel à la portion de graphe effectivement parcourue, et un langage (Cypher, Gremlin) exprimant nativement la profondeur variable. Le distracteur 2 invente un O(1) magique. Le 3 est faux : le relationnel modélise très bien le many-to-many (table de jonction). Le 4 est inventé.","tags":["modèle-graphe","parcours-transitif","cypher","recursive-cte","ddia"]},
  {"id":"db-stockage-oriente-colonnes-et-compression","type":"mcq","domain":"software","topic":"databases","difficulty":"senior","title":"Stockage orienté colonnes et compression","company":"Kleppmann, DDIA, chap. 3, « Column-Oriented Storage »","question":"Un entrepôt analytique passe d'un stockage orienté lignes à orienté colonnes. Au-delà de « ne lire que les colonnes utiles », quel mécanisme spécifique décuple la compression et le débit des requêtes analytiques ?","options":["Stocker chaque colonne séparément regroupe des valeurs du même type et souvent peu distinctes, permettant un encodage très efficace (bitmap/RLE) et un traitement vectorisé qui tient dans le cache CPU","Le stockage colonne réplique chaque colonne sur tous les nœuds, si bien que la compression vient de la déduplication inter-nœuds ; le gain de débit provient du quorum de lecture réduit à un seul réplica","Chaque colonne devient un index B-tree autonome, donc toute requête analytique est un index-only scan ; la compression résulte de la suppression des pointeurs heap devenus inutiles","Le format colonne convertit les valeurs en JSON compressé par colonne, ce qui uniformise les types hétérogènes ; le débit augmente parce que le JSON se parse plus vite que des lignes binaires"],"answer":0,"explanation":"En stockage colonne, toutes les valeurs d'une colonne sont contiguës : elles partagent le type et présentent souvent une faible cardinalité ou des répétitions, ce qui rend très efficaces les encodages comme le bitmap encoding et le run-length encoding (RLE) — Kleppmann détaille le bitmap encoding pour les colonnes à peu de valeurs distinctes. De plus, ces colonnes compressées se traitent par lots vectorisés tenant dans le cache CPU/registres SIMD, d'où un débit analytique décuplé. Les distracteurs inventent des mécanismes : réplication/quorum (2), B-tree par colonne (3), JSON (4) — aucun ne décrit le vrai gain (compression columnar + vectorisation).","tags":["stockage-colonnes","compression","vectorisation","olap","ddia"]},
  {"id":"db-uuidv4-en-cle-primaire-fragmentation-d-i","type":"find-error","domain":"software","topic":"databases","difficulty":"senior","title":"UUIDv4 en clé primaire : fragmentation d'index","company":"Markus Winand, « Use The Index, Luke » ; doc PostgreSQL sur les B-tree page splits","language":"sql","code":"CREATE TABLE evenements (\n  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,\n  charge JSONB NOT NULL,\n  cree_le TIMESTAMPTZ DEFAULT now()\n);\n-- des dizaines de milliers d'INSERT par seconde","question":"Un schéma utilise `id UUID DEFAULT gen_random_uuid() PRIMARY KEY` sur une table à très forte insertion. Les DBA observent une dégradation des insertions et un gonflement de l'index primaire. Quelle est la cause structurelle et la mitigation ?","options":["Les UUIDv4 sont aléatoires : chaque insertion vise une feuille B-tree imprévisible, provoquant des page splits fréquents, une mauvaise localité de cache et de la fragmentation ; une clé temporellement ordonnée (UUIDv7, bigint séquentiel) restaure des insertions en fin d'index","Le type UUID occupe 128 bits, ce qui dépasse la taille de page B-tree de PostgreSQL et force un stockage TOAST par ligne ; passer en `uuid` compressé ou en `text` de 36 octets réduit le gonflement","gen_random_uuid() prend un verrou global de génération, sérialisant les insertions ; remplacer par une séquence `nextval()` supprime le verrou et corrige à la fois la latence et la fragmentation","Le problème est l'absence de FILLFACTOR : les UUID remplissent les pages à 100%, empêchant les updates HOT ; abaisser fillfactor à 70 résout la fragmentation sans changer le type de clé"],"answer":0,"explanation":"Un UUIDv4 est aléatoire : les valeurs successives insérées tombent à des emplacements dispersés de l'index B-tree primaire. Sur une table à insertions massives, cela déclenche de fréquents page splits (division de feuilles pleines), détruit la localité (chaque insert touche une page froide différente, mauvais taux de cache) et fragmente l'index qui gonfle. Une clé ORDONNÉE dans le temps (bigint séquentiel, ou UUIDv7 qui préfixe un timestamp) fait toujours insérer en fin d'index, sur la même page chaude : splits minimaux, remplissage dense, meilleure localité. Le distracteur 2 est faux (128 bits n'a rien à voir avec TOAST, l'UUID tient largement). Le 3 invente un verrou global. Le 4 confond fillfactor/HOT (les HOT concernent les UPDATE, pas ce cas d'INSERT) et ne traite pas la cause (l'aléa des clés).","tags":["uuid","page-split","fragmentation","clé-primaire","sql"]},
  {"id":"db-pagination-offset-vs-keyset","type":"mcq","domain":"software","topic":"databases","difficulty":"senior","title":"Pagination OFFSET vs keyset","company":"Markus Winand, « Use The Index, Luke », chap. « Paging Through Results »","question":"Une API pagine avec `ORDER BY cree_le DESC LIMIT 20 OFFSET :n`. Les pages profondes (OFFSET 100000) deviennent très lentes. Pourquoi, et que propose la pagination keyset ?","options":["OFFSET oblige le SGBD à lire et jeter toutes les lignes précédentes (100000) avant d'en renvoyer 20, coût croissant avec la profondeur ; le keyset filtre `WHERE cree_le < :dernier_vu ORDER BY cree_le DESC LIMIT 20`, en démarrant directement au bon endroit via l'index","OFFSET recalcule un tri complet à chaque page car il invalide le cache de plan ; le keyset le contourne en matérialisant un curseur serveur qui garde le tri en mémoire entre les requêtes","Les pages profondes sont lentes car OFFSET force un seq scan au-delà de work_mem ; le keyset augmente implicitement work_mem pour garder tout le tri en RAM et retrouve un accès constant","OFFSET verrouille en lecture toutes les lignes sautées pour garantir la cohérence de pagination, d'où la lenteur ; le keyset relâche ces verrous en acceptant une pagination approximative non répétable"],"answer":0,"explanation":"Winand : `OFFSET n` n'a pas de raccourci — le moteur doit produire (dans l'ordre du tri) et PARCOURIR les n premières lignes pour ensuite les JETER, ne conservant que les 20 suivantes. Le coût croît linéairement avec l'OFFSET, d'où l'effondrement des pages profondes. La pagination keyset (seek method) mémorise la valeur de tri de la dernière ligne vue et filtre `WHERE cree_le < :dernier_vu ORDER BY cree_le DESC LIMIT 20` : l'index positionne DIRECTEMENT le point de départ, coût constant quelle que soit la profondeur (et stable face aux insertions). Les distracteurs 2/3/4 inventent des causes (cache de plan, work_mem, verrous) qui ne correspondent pas au mécanisme réel de l'OFFSET.","tags":["pagination","offset","keyset","seek-method","use-the-index-luke"]},
  {"id":"db-foreign-key-sans-index-et-verrouillage","type":"mcq","domain":"software","topic":"databases","difficulty":"senior","title":"Foreign key sans index et verrouillage","company":"Documentation PostgreSQL, « Foreign Keys » ; Winand sur les index de clés étrangères","question":"Une table `lignes_commande(commande_id REFERENCES commandes)` n'a PAS d'index sur `commande_id`. Quel problème de performance/verrouillage précis en résulte, distinct du simple ralentissement des JOINs ?","options":["Chaque suppression/mise à jour de clé dans `commandes` doit vérifier l'absence de lignes filles référençantes ; sans index sur `commande_id`, cette vérification fait un seq scan de `lignes_commande` et peut prendre des verrous prolongés, ralentissant fortement les DELETE parents","L'absence d'index sur la FK empêche PostgreSQL de créer la contrainte : la commande `REFERENCES` échouerait au CREATE TABLE tant qu'aucun index n'existe côté enfant, donc le schéma est invalide dès le départ","Sans index, chaque INSERT dans `lignes_commande` prend un verrou exclusif sur toute la table `commandes` pour valider la FK, sérialisant toutes les insertions de lignes de commande","Le manque d'index force la contrainte à être vérifiée en DEFERRED, ce qui accumule les validations jusqu'au COMMIT et fait exploser la mémoire de transaction sur les gros lots"],"answer":0,"explanation":"PostgreSQL crée automatiquement un index sur la colonne RÉFÉRENCÉE (la PK de `commandes`), mais PAS sur la colonne référençante `lignes_commande.commande_id`. Or, quand on DELETE/UPDATE une ligne parente, le SGBD doit vérifier qu'aucune ligne fille ne la référence (ou cascader) : sans index sur `commande_id`, cette recherche est un seq scan de la table fille, potentiellement énorme, et prend des verrous sur les lignes examinées, allongeant la durée des opérations parentes et la contention. D'où la recommandation d'indexer les FK. Le distracteur 2 est faux (la contrainte se crée sans index enfant). Le 3 invente un verrou table exclusif. Le 4 confond avec les contraintes DEFERRABLE.","tags":["foreign-key","index","verrouillage","delete-cascade","postgresql"]},
  {"id":"db-phantom-read-et-verrous-de-predicat","type":"mcq","domain":"software","topic":"databases","difficulty":"senior","title":"Phantom read et verrous de prédicat","company":"Kleppmann, DDIA, chap. 7 ; norme SQL isolation levels","question":"Sous quelle condition exacte un « phantom read » se produit-il, et pourquoi REPEATABLE READ au sens de la norme SQL ne suffit-il pas toujours à l'empêcher là où PostgreSQL, lui, l'empêche ?","options":["Un phantom apparaît quand une transaction ré-exécute une requête à prédicat de plage et voit apparaître/disparaître des lignes insérées/supprimées par une autre ; la norme n'exige des verrous que sur les lignes lues, alors que le REPEATABLE READ de PostgreSQL, fondé sur un snapshot, fige aussi les insertions concurrentes","Un phantom est une lecture d'une ligne non validée ; la norme SQL REPEATABLE READ l'autorise explicitement tandis que PostgreSQL le bloque en prenant un verrou exclusif sur chaque page lue pendant toute la transaction","Un phantom survient uniquement lors d'un UPDATE sur une même ligne par deux transactions ; PostgreSQL le prévient par un verrou de ligne SELECT FOR SHARE implicite absent de la norme","Un phantom est un cas de dirty write ; la norme le tolère en READ COMMITTED, et PostgreSQL l'élimine en promouvant automatiquement toute transaction en SERIALIZABLE dès qu'un prédicat de plage est détecté"],"answer":0,"explanation":"Un phantom read : une transaction exécute une requête retournant un ensemble de lignes correspondant à un PRÉDICAT (ex. `WHERE solde > 1000`), et une autre transaction insère/supprime des lignes vérifiant ce prédicat ; en ré-exécutant, la première voit des lignes « fantômes » apparues ou disparues. La norme SQL au niveau REPEATABLE READ (verrouillage 2PL classique) ne verrouille que les lignes lues, pas les lignes futures, d'où phantoms possibles ; empêcher cela exige des verrous de prédicat/range (SERIALIZABLE). PostgreSQL implémente REPEATABLE READ via un SNAPSHOT (SI) : la transaction voit un instantané figé, donc ne voit PAS les insertions concurrentes — les phantoms de LECTURE sont évités (mais le write skew subsiste, d'où SERIALIZABLE/SSI). Les distracteurs confondent phantom avec dirty read/write et inventent des verrous.","tags":["phantom-read","repeatable-read","snapshot-isolation","prédicat","ddia"]},
  {"id":"db-serialisabilite-ssi-vs-2pl","type":"mcq","domain":"software","topic":"databases","difficulty":"senior","title":"Sérialisabilité : SSI vs 2PL","company":"Kleppmann, DDIA, chap. 7, « Serializable Snapshot Isolation (SSI) »","question":"PostgreSQL implémente SERIALIZABLE via Serializable Snapshot Isolation (SSI), une technique optimiste. En quoi diffère-t-elle fondamentalement du Two-Phase Locking (2PL), et quel en est le principal inconvénient opérationnel ?","options":["SSI laisse les transactions s'exécuter sur snapshot sans se bloquer, puis détecte a posteriori les dépendances rw dangereuses et ABORTE une transaction fautive au commit ; l'inconvénient est un taux d'abort/retry élevé sous forte contention","SSI verrouille chaque objet lu ET écrit dès l'accès comme 2PL, mais libère les verrous de lecture au premier commit ; son inconvénient est l'interblocage plus fréquent qu'en 2PL classique","SSI et 2PL sont identiques en comportement observable ; SSI n'est qu'une réécriture interne plus rapide, sans différence de débit, de latence ni de risque d'abort pour l'application","SSI garantit l'absence totale d'abort en pré-ordonnant globalement les transactions par timestamp ; son coût est une latence fixe ajoutée à chaque commit pour synchroniser l'horloge logique"],"answer":0,"explanation":"2PL est PESSIMISTE : il prend des verrous (partagés en lecture, exclusifs en écriture) et bloque toute transaction en conflit, garantissant la sérialisabilité au prix de blocages et d'un débit réduit sous contention. SSI est OPTIMISTE : les transactions s'exécutent sur un snapshot sans se bloquer mutuellement ; le moteur suit les dépendances lecture-écriture (rw-antidependencies) et, s'il détecte un motif pouvant violer la sérialisabilité, il ABORTE l'une des transactions au moment du commit. Avantage : bonne concurrence quand les conflits sont rares ; inconvénient opérationnel : sous forte contention, beaucoup de transactions sont abortées et doivent être rejouées (retry), gaspillant du travail. Les distracteurs 2/3/4 décrivent mal SSI (ce n'est pas du verrouillage, pas identique à 2PL, et il n'élimine pas les aborts).","tags":["ssi","serializable","2pl","optimiste","ddia"]},
  {"id":"db-read-committed-ce-qu-il-garantit-vraimen","type":"mcq","domain":"software","topic":"databases","difficulty":"senior","title":"Read committed : ce qu'il garantit vraiment","company":"Documentation PostgreSQL, « Transaction Isolation / Read Committed »","question":"Sous READ COMMITTED (défaut PostgreSQL), quelle garantie EXACTE tient, et quelle anomalie reste possible AU SEIN d'une même transaction longue ?","options":["Aucun dirty read (on ne lit que des données validées), mais chaque instruction voit un nouveau snapshot : deux SELECT successifs peuvent renvoyer des valeurs différentes (non-repeatable read) si une autre transaction commite entre-temps","Pas de non-repeatable read (le snapshot est figé au BEGIN), mais des dirty reads restent possibles car READ COMMITTED autorise la lecture d'écritures non validées d'autres transactions","Aucune anomalie de lecture n'est possible ; READ COMMITTED est équivalent à SERIALIZABLE pour les lectures et ne diffère que sur la gestion des écritures concurrentes","Les phantom reads sont éliminés mais les lost updates sont garantis impossibles automatiquement, PostgreSQL réappliquant l'écriture sur la version la plus récente de façon transparente"],"answer":0,"explanation":"READ COMMITTED en PostgreSQL : chaque INSTRUCTION prend un nouveau snapshot des données VALIDÉES au moment où elle démarre. Conséquences exactes : (1) pas de dirty read — on ne voit jamais d'écriture non validée ; (2) MAIS non-repeatable read possible — deux SELECT dans la même transaction peuvent voir des valeurs différentes si une autre transaction a commité entre les deux (et les phantoms aussi). Le distracteur 2 inverse (le snapshot n'est PAS figé au BEGIN sous READ COMMITTED — ça, c'est REPEATABLE READ — et les dirty reads n'existent pas). Le 3 est faux (READ COMMITTED autorise plusieurs anomalies). Le 4 est faux (les lost updates restent possibles, cf. exercice sur le sujet).","tags":["read-committed","non-repeatable-read","snapshot","isolation","postgresql"]},
  {"id":"db-deadlock-par-ordre-d-acquisition","type":"find-error","domain":"software","topic":"databases","difficulty":"senior","title":"Deadlock par ordre d'acquisition","company":"Documentation PostgreSQL, « Explicit Locking / Deadlocks »","language":"sql","code":"-- virement de :src vers :dst\nBEGIN;\n  UPDATE comptes SET solde = solde - :montant WHERE id = :src;\n  UPDATE comptes SET solde = solde + :montant WHERE id = :dst;\nCOMMIT;","question":"Ce code de virement entre comptes provoque des interblocages aléatoires en production sous charge. Quelle est la cause exacte et le remède standard ?","options":["Deux virements A→B et B→A verrouillent les lignes dans des ordres opposés (T1 lock A puis B, T2 lock B puis A) : chacun attend le verrou détenu par l'autre → deadlock ; il faut toujours verrouiller les comptes dans un ordre total déterministe (ex. par id croissant)","Le deadlock vient de l'absence de `SELECT FOR UPDATE` : sans verrou explicite les UPDATE se font en READ COMMITTED, et PostgreSQL crée un verrou de prédicat global qui s'auto-bloque ; ajouter FOR SHARE résout le cycle","La cause est le débit d'écriture qui dépasse le nombre de connexions du pool ; augmenter `max_connections` élimine l'attente circulaire en donnant à chaque virement sa propre connexion sans contention de verrou","Le problème est l'usage de deux UPDATE séparés au lieu d'un seul ; PostgreSQL ne peut garantir l'atomicité qu'avec une unique instruction, et deux UPDATE dans une transaction créent toujours un deadlock sous charge"],"answer":0,"explanation":"Chaque UPDATE prend un verrou de ligne (row lock) sur le compte modifié. Un virement A→B verrouille A puis B ; un virement concurrent B→A verrouille B puis A. Si T1 tient A et demande B pendant que T2 tient B et demande A, on obtient une attente circulaire = deadlock. PostgreSQL le détecte et aborte l'une des transactions, mais cela génère des erreurs et des retries. Remède canonique : imposer un ORDRE TOTAL d'acquisition des verrous, par exemple verrouiller toujours le compte de plus petit id en premier (`ORDER BY id` / trier src,dst), ce qui rend impossible le cycle. Les distracteurs 2/3/4 attribuent le deadlock à des causes inexistantes (verrou de prédicat global, pool de connexions, atomicité des UPDATE).","tags":["deadlock","lock-ordering","for-update","concurrence","sql"]},
  {"id":"db-bloom-filter-dans-un-lsm-tree","type":"mcq","domain":"software","topic":"databases","difficulty":"senior","title":"Bloom filter dans un LSM-tree","company":"Kleppmann, DDIA, chap. 3, « Making an LSM-tree out of SSTables / Performance optimizations »","question":"Un moteur LSM (LevelDB/RocksDB) utilise des bloom filters. Quel problème précis résolvent-ils, et quelle est leur limite intrinsèque à comprendre pour le dimensionnement ?","options":["Ils évitent des lectures disque inutiles pour les clés ABSENTES : un bloom filter peut affirmer avec certitude qu'une clé n'est pas dans une SSTable, mais admet des faux positifs (jamais de faux négatifs), à ajuster via le nombre de bits par clé","Ils garantissent l'unicité des clés à l'écriture en rejetant les doublons avant la compaction ; leur limite est qu'ils produisent des faux négatifs, laissant passer de rares doublons corrigés à la compaction suivante","Ils accélèrent les lectures de plage en pré-triant les clés par hash ; leur limite est de ne fonctionner que sur des clés numériques contiguës, inutilisables pour des clés textuelles","Ils compressent les SSTables en remplaçant les clés par leur empreinte ; leur limite est une collision possible qui corrompt la valeur associée, d'où la nécessité d'un checksum par bloc"],"answer":0,"explanation":"Dans un LSM, une lecture peut devoir consulter plusieurs SSTables ; pour une clé qui N'EXISTE PAS, ce serait autant d'accès disque inutiles. Un bloom filter est une structure probabiliste compacte qui répond à « la clé pourrait-elle être ici ? » : s'il répond NON, la clé est certainement absente (on évite l'accès disque) ; s'il répond OUI, elle est PEUT-ÊTRE présente (faux positif possible). Propriété clé : pas de faux négatifs, mais des faux positifs dont le taux dépend du nombre de bits par clé et de fonctions de hash — d'où l'arbitrage mémoire/taux de faux positifs au dimensionnement. Les distracteurs inventent des rôles (unicité, tri de plage, compression) et attribuent à tort des faux négatifs (2) ou des collisions corruptrices (4).","tags":["bloom-filter","lsm-tree","faux-positifs","sstable","ddia"]},
  {"id":"db-monotonic-reads-et-coherence-de-session","type":"mcq","domain":"software","topic":"databases","difficulty":"senior","title":"Monotonic reads et cohérence de session","company":"Kleppmann, DDIA, chap. 5, « Monotonic Reads »","question":"Un utilisateur rafraîchit une page et voit un commentaire, puis au rafraîchissement suivant ce commentaire a DISPARU, bien qu'il ait été validé. Quelle anomalie de réplication est-ce, et quelle garantie l'empêche ?","options":["C'est une violation de la lecture monotone : deux lectures successives ont atterri sur des followers à des niveaux de lag différents (le second plus en retard) ; garantir « monotonic reads » (router un même utilisateur toujours vers le même réplica) empêche ce retour en arrière temporel","C'est un dirty read : le commentaire non validé a été lu puis annulé ; passer en READ COMMITTED sur les followers empêche de lire des écritures non confirmées et supprime la disparition","C'est un write skew de réplication : deux followers ont résolu un conflit d'insertion différemment ; activer LWW sur les commentaires garantit qu'ils réapparaissent de façon déterministe","C'est un phantom read causé par un OFFSET instable ; passer en pagination keyset stabilise l'ordre et empêche la disparition apparente du commentaire entre deux rafraîchissements"],"answer":0,"explanation":"Anomalie de « lecture non monotone » : avec plusieurs followers de lags différents, une première lecture peut tomber sur un follower à jour (voit le commentaire) et la suivante sur un follower plus en retard (ne le voit pas encore) — l'utilisateur remonte le temps. La garantie de MONOTONIC READS assure que, si un client a vu une donnée, ses lectures ultérieures ne verront jamais un état antérieur ; on l'obtient typiquement en routant chaque utilisateur TOUJOURS vers le même réplica (ex. hash de l'user id). Ce n'est pas un dirty read (le commentaire était validé, distracteur 2), ni un write skew/LWW (3), ni un artefact d'OFFSET (4).","tags":["monotonic-reads","réplication","lag","cohérence-session","ddia"]},
  {"id":"db-index-composite-inutilise-pour-le-tri","type":"find-error","domain":"software","topic":"databases","difficulty":"senior","title":"Index composite inutilisé pour le tri","company":"Markus Winand, « Use The Index, Luke », chap. « Indexing Order By »","language":"sql","code":"-- index: CREATE INDEX ON evenements (client_id, cree_le);\nSELECT * FROM evenements\n ORDER BY cree_le DESC\n LIMIT 50;","question":"L'index `(client_id, cree_le)` existe. La requête ci-dessous fait quand même un tri explicite (`Sort` dans EXPLAIN) coûteux. Pourquoi l'index ne fournit-il pas l'ordre gratuitement, et comment corriger ?","options":["La requête ne fixe pas `client_id` par égalité et trie sur `cree_le` seul : les feuilles étant ordonnées d'abord par `client_id`, l'ordre global ne suit pas `cree_le` ; il faut soit filtrer `client_id = ?`, soit un index dédié sur `(cree_le DESC)`","L'index n'est pas utilisé pour le tri car `ORDER BY` requiert un index `USING brin` ; les B-tree ne préservent jamais l'ordre au-delà de la première colonne, il faut donc reconstruire l'index en BRIN sur `cree_le`","Le `Sort` apparaît parce que `LIMIT 50` désactive l'usage ordonné de l'index ; retirer le LIMIT laisse PostgreSQL exploiter l'ordre des feuilles et supprime le tri","Le tri vient d'un `cree_le` de type timestamptz non indexable en ordre ; caster en `date` dans l'ORDER BY réaligne l'ordre lexicographique de l'index composite et élimine le Sort"],"answer":0,"explanation":"Un index `(client_id, cree_le)` trie les feuilles d'abord par `client_id`, puis par `cree_le` À L'INTÉRIEUR de chaque client. L'ordre global des feuilles suit donc `cree_le` UNIQUEMENT pour un `client_id` fixé. La requête ne filtre pas `client_id` : elle veut tous les événements triés par `cree_le` seul, ce que l'index ne fournit pas dans le bon ordre → PostgreSQL doit trier explicitement (Sort). Winand : pour qu'un index composite serve un ORDER BY, il faut soit une égalité sur les colonnes de tête, soit que la colonne triée soit en tête. Corrections : filtrer `client_id = ?` (l'ORDER BY cree_le devient gratuit), ou créer un index dédié `(cree_le DESC)`. Les distracteurs 2/3/4 inventent des causes (BRIN, LIMIT, cast) sans rapport.","tags":["index-composite","order-by","tri","use-the-index-luke","sql"]},
  {"id":"db-sharding-choix-de-la-cle-de-partition","type":"mcq","domain":"software","topic":"databases","difficulty":"senior","title":"Sharding : choix de la clé de partition","company":"Kleppmann, DDIA, chap. 6 ; « Partitioning and Secondary Indexes »","question":"On shard une base multi-tenant par `tenant_id` (hash). Un tenant géant (« whale ») déséquilibre son shard, et beaucoup de requêtes analytiques cross-tenant deviennent lentes. Quel arbitrage fondamental ce choix de clé illustre-t-il ?","options":["La clé de partition optimise la localité d'un type d'accès au détriment d'un autre : `tenant_id` colocalise les données d'un tenant (bon pour les requêtes mono-tenant) mais crée des hotspots pour les whales et impose du scatter-gather pour les requêtes cross-tenant","Sharder par `tenant_id` est un anti-pattern absolu ; il faut toujours sharder par clé primaire aléatoire pour garantir un équilibre parfait, ce qui rend inutile toute requête cross-tenant","Le déséquilibre prouve que le hash est mal choisi ; passer d'un hash à un partitionnement par plage de `tenant_id` équilibre automatiquement les whales sur plusieurs shards","Les requêtes cross-tenant lentes viennent uniquement d'un manque d'index secondaire global ; ajouter un index global sur chaque shard supprime le scatter-gather sans changer la clé"],"answer":0,"explanation":"Le choix de la clé de partition est un arbitrage de LOCALITÉ. Sharder par `tenant_id` colocalise toutes les données d'un tenant sur un shard : excellent pour les requêtes mono-tenant (elles touchent un seul shard), mais (a) un tenant énorme surcharge son shard (hotspot/déséquilibre non résoluble par le hash puisque même clé = même shard) et (b) les requêtes cross-tenant doivent interroger TOUS les shards puis agréger (scatter-gather), coûteux. Il n'existe pas de clé parfaite : optimiser un pattern d'accès en pénalise un autre. Le distracteur 2 (clé aléatoire toujours meilleure) ignore la localité mono-tenant. Le 3 (range) n'équilibre pas une clé unique surchargée. Le 4 (index global) n'élimine pas le scatter-gather d'un partitionnement par document.","tags":["sharding","partition-key","multi-tenant","scatter-gather","ddia"]},
  {"id":"db-compteur-incremente-avec-race-condition","type":"find-error","domain":"software","topic":"databases","difficulty":"senior","title":"Compteur incrémenté avec race condition","company":"CWE-362: Concurrent Execution using Shared Resource with Improper Synchronization","language":"go","code":"func incrementViews(db *sql.DB, id int64) error {\n    var vues int64\n    err := db.QueryRow(\"SELECT vues FROM articles WHERE id=$1\", id).Scan(&vues)\n    if err != nil {\n        return err\n    }\n    _, err = db.Exec(\"UPDATE articles SET vues=$1 WHERE id=$2\", vues+1, id)\n    return err\n}","question":"Ce code Go incrémente un compteur de vues. Sous forte concurrence, des incréments sont perdus. Quel est le défaut, sachant que le pool de connexions autorise le parallélisme ?","options":["Le read-modify-write (SELECT puis UPDATE avec la valeur lue) n'est pas atomique : deux goroutines lisent la même valeur et écrivent le même +1 ; il faut un UPDATE atomique `SET vues = vues + 1` exécuté côté SGBD","Le bug est l'absence de `defer rows.Close()` : les connexions fuient, le pool s'épuise et certaines requêtes d'incrément échouent silencieusement sans erreur remontée","Le problème est l'usage de `QueryRow` au lieu de `Exec` pour l'UPDATE ; `QueryRow` ne valide pas la transaction, donc l'incrément est rollbacké à la fermeture de la connexion","Le défaut est l'absence de `context.WithTimeout` : sans délai, les UPDATE concurrents se bloquent mutuellement et PostgreSQL en annule certains par timeout de deadlock"],"answer":0,"explanation":"Classique race de read-modify-write non atomique : deux goroutines exécutent `SELECT vues` (obtiennent par ex. 100 chacune), calculent 101 côté Go, puis écrivent 101 toutes les deux — un incrément est perdu. Le calcul se fait dans l'application entre deux appels indépendants, sans verrou ni atomicité. Correction : déléguer l'arithmétique au SGBD avec un UPDATE atomique `SET vues = vues + 1 WHERE id = $1` (l'incrément est fait sous verrou de ligne, sérialisé correctement) ; ou `SELECT ... FOR UPDATE` dans une transaction ; ou un type/compteur adapté. Les distracteurs 2/3/4 pointent des problèmes réels ailleurs (fuite de curseur, transaction, timeout) mais AUCUN n'explique la perte d'incréments, qui vient bien de la non-atomicité du read-modify-write.","tags":["race-condition","read-modify-write","atomicité","cwe-362","go"]},
  {"id":"db-index-couvrant-vs-include-difference-sub","type":"mcq","domain":"software","topic":"databases","difficulty":"senior","title":"Index couvrant vs INCLUDE : différence subtile","company":"Documentation PostgreSQL, « CREATE INDEX / INCLUDE » ; Winand sur les index couvrants","question":"Quelle différence exacte y a-t-il entre mettre une colonne dans la CLÉ de l'index `(a, b)` versus l'ajouter en `(a) INCLUDE (b)`, pour couvrir `SELECT b WHERE a = ?` ?","options":["Dans les deux cas `b` est disponible sans accès au heap, mais en INCLUDE `b` n'est stocké que dans les feuilles (pas dans les nœuds internes) et n'est ni trié ni utilisable pour un prédicat/tri sur `b` — utile pour un index unique sur `a` seul","En INCLUDE, `b` est trié dans l'index exactement comme s'il faisait partie de la clé, la seule différence étant que INCLUDE interdit l'unicité ; les deux formes sont interchangeables pour l'optimiseur","La clé `(a, b)` ne couvre pas la requête car `b` en position 2 n'est lisible qu'après un accès heap, alors que INCLUDE stocke `b` hors index dans une table annexe consultée sans random I/O","INCLUDE stocke `b` compressé dans les nœuds internes du B-tree, réduisant la profondeur de l'arbre, tandis que `(a, b)` gonfle chaque niveau ; INCLUDE est donc toujours préférable pour couvrir"],"answer":0,"explanation":"Les deux formes rendent `b` disponible depuis l'index (index-only scan possible pour `SELECT b WHERE a = ?`). La différence : une colonne INCLUDE (payload) n'est stockée que dans les FEUILLES du B-tree, pas dans les nœuds internes, n'est pas triée, et ne peut donc pas servir à des prédicats de plage, à un ORDER BY sur `b`, ni compter dans une contrainte d'unicité. Intérêt majeur d'INCLUDE : créer un index UNIQUE sur `(a)` seul tout en couvrant `b`, ce qu'une clé `(a, b)` ne permettrait pas (l'unicité porterait sur le couple). Le distracteur 2 est faux (b n'est pas trié en INCLUDE). Le 3 est faux (une clé (a,b) couvre bien b sans heap). Le 4 invente un stockage dans les nœuds internes (c'est l'inverse).","tags":["index-couvrant","include","index-unique","b-tree","postgresql"]},
  {"id":"db-schema-type-d-argent-en-flottant","type":"find-error","domain":"software","topic":"databases","difficulty":"senior","title":"Schéma : type d'argent en flottant","company":"Documentation PostgreSQL, « Numeric Types » ; PostgreSQL wiki « Don't use float for money »","language":"sql","code":"CREATE TABLE lignes_facture (\n  id BIGSERIAL PRIMARY KEY,\n  facture_id BIGINT NOT NULL,\n  montant DOUBLE PRECISION NOT NULL,\n  quantite INT NOT NULL\n);","question":"Ce schéma de facturation produit des écarts d'un centime lors des sommes et comparaisons. Quel est le défaut de conception et sa correction ?","options":["`montant DOUBLE PRECISION` stocke un flottant binaire IEEE 754 qui ne représente pas exactement les décimaux comme 0,10 ; il faut `NUMERIC(12,2)` (décimal exact) pour les montants monétaires","Le défaut est l'absence de `CHECK (montant >= 0)` ; les erreurs d'arrondi viennent de montants négatifs implicites, corrigés par la contrainte sans changer le type double","`DOUBLE PRECISION` est correct pour l'argent mais il faut arrondir à la lecture avec `ROUND(montant, 2)` ; le vrai bug est l'absence de collation numérique sur la colonne","Le problème est que `DOUBLE PRECISION` ne tient pas les grands montants au-delà de 2^53 ; passer en `BIGINT` de centimes est la seule cause de l'écart et suffit sans revoir les arrondis"],"answer":0,"explanation":"`DOUBLE PRECISION` est un flottant binaire IEEE 754 : des valeurs décimales anodines comme 0,10 ou 0,20 n'ont pas de représentation binaire exacte, donc les sommes et comparaisons accumulent des erreurs d'arrondi (le fameux écart d'un centime). Pour la monnaie, il faut un type DÉCIMAL EXACT : `NUMERIC(precision, scale)` (ex. `NUMERIC(12,2)`), qui stocke les décimaux sans perte — ou, alternative courante, des entiers de centimes (BIGINT) avec arithmétique entière maîtrisée. Le distracteur 2 (CHECK) n'a rien à voir avec l'arrondi. Le 3 est faux : arrondir à la lecture ne guérit pas les erreurs accumulées, et la « collation numérique » n'existe pas ici. Le 4 identifie un vrai problème de double (précision au-delà de 2^53) mais ce n'est PAS la cause des écarts au centime sur de petits montants — la cause est la non-exactitude décimale du binaire.","tags":["numeric","float","monnaie","arrondi","sql"]},
  {"id":"db-replication-synchrone-vs-asynchrone-le-c","type":"mcq","domain":"software","topic":"databases","difficulty":"senior","title":"Réplication synchrone vs asynchrone : le compromis","company":"Kleppmann, DDIA, chap. 5, « Synchronous Versus Asynchronous Replication »","question":"En leader-follower, on hésite entre réplication synchrone et asynchrone. Quelle description est exacte, y compris pour la configuration « semi-synchrone » recommandée par Kleppmann ?","options":["Synchrone : le commit attend l'accusé d'au moins un follower (aucune perte si le leader tombe, mais un follower lent bloque les écritures) ; asynchrone : commit immédiat (rapide mais perte possible en cas de panne) ; semi-synchrone : un seul follower synchrone, les autres asynchrones","Synchrone : tous les followers doivent accuser réception, garantissant zéro latence supplémentaire ; asynchrone : le leader attend un quorum ; semi-synchrone : alterne les deux modes selon la charge CPU du leader mesurée en continu","Asynchrone garantit l'absence de perte de données car le WAL est répliqué avant le commit ; synchrone au contraire accepte la perte pour gagner en débit ; le semi-synchrone n'existe que sur les bases multi-leader","En synchrone, si le follower tombe le leader continue seul sans blocage, donc synchrone n'a aucun inconvénient de disponibilité ; l'asynchrone n'est utile que pour les sauvegardes froides"],"answer":0,"explanation":"Kleppmann : en réplication SYNCHRONE, le leader attend la confirmation d'un follower avant de signaler le commit au client — garantie forte (le follower a la donnée, pas de perte si le leader échoue) mais si ce follower est lent ou en panne, TOUTES les écritures se bloquent. En ASYNCHRONE, le leader confirme sans attendre — écritures rapides et robustes aux followers lents, mais si le leader tombe avant réplication, les écritures non répliquées sont PERDUES. Le compromis SEMI-SYNCHRONE : UN follower est synchrone (garantie qu'au moins deux nœuds ont la donnée), les autres asynchrones ; si le synchrone ralentit, un asynchrone est promu synchrone. Les distracteurs 2/3/4 mélangent les propriétés (latence, perte, disponibilité) de façon incorrecte.","tags":["réplication","synchrone","asynchrone","semi-synchrone","ddia"]},
  {"id":"db-toast-et-lignes-larges","type":"mcq","domain":"software","topic":"databases","difficulty":"senior","title":"TOAST et lignes larges","company":"Documentation PostgreSQL, « TOAST »","question":"Une table avec une grosse colonne `JSONB` rarement lue mais très volumineuse ralentit les scans qui ne lisent QUE les petites colonnes. Comment le mécanisme TOAST de PostgreSQL intervient-il, et quel piège subsiste ?","options":["Au-delà d'un seuil (~2 Ko), PostgreSQL déporte la valeur volumineuse dans une table TOAST à part et ne garde qu'un pointeur dans la ligne principale, gardant les scans des petites colonnes rapides ; le piège est qu'un accès à la colonne toastée ajoute un lookup, et un mauvais réglage (PLAIN) désactive ce déport","TOAST compresse toute la ligne en un seul blob binaire ; le piège est que lire une petite colonne décompresse d'abord la ligne entière, d'où le ralentissement, corrigé en désactivant la compression","TOAST réplique la grosse colonne sur les followers uniquement, allégeant le leader ; le piège est que les scans sur le leader restent lents tant qu'on ne lit pas depuis un follower","TOAST indexe automatiquement la colonne JSONB en GIN pour éviter de la scanner ; le piège est le coût de maintenance de cet index implicite sur les écritures fréquentes"],"answer":0,"explanation":"TOAST (The Oversized-Attribute Storage Technique) : quand une ligne dépasse ~2 Ko, PostgreSQL compresse et/ou déporte les grandes valeurs à longueur variable (comme un gros JSONB) dans une table TOAST associée, ne laissant qu'un pointeur dans le tuple principal. Résultat : la ligne principale reste petite, donc un seq scan qui ne lit que les petites colonnes n'a pas à charger le gros JSONB — il reste rapide. Piège : dès qu'une requête accède réellement à la colonne toastée, un lookup supplémentaire (dé-TOAST) s'ajoute ; et régler le storage en PLAIN empêcherait le déport (lignes larges, scans lents). Les distracteurs 2/3/4 décrivent mal TOAST (pas de blob global de ligne, pas de réplication sélective, pas d'index GIN implicite).","tags":["toast","jsonb","stockage","seq-scan","postgresql"]},
  {"id":"db-transaction-laissee-ouverte-idle-in-tran","type":"find-error","domain":"software","topic":"databases","difficulty":"senior","title":"Transaction laissée ouverte (idle in transaction)","company":"Documentation PostgreSQL, « idle_in_transaction_session_timeout » ; MVCC/vacuum","language":"python","code":"tx = db.begin()\ntx.execute(\"INSERT INTO commandes(...) VALUES (...)\")\nresultat = http.post(\"https://paiement.externe/api\", ...)  # 2-5 s\ntx.execute(\"UPDATE commandes SET paiement=%s WHERE ...\", resultat)\ntx.commit()","question":"Ce pseudo-code de service ouvre une transaction, appelle une API externe lente, puis commite. En production cela bloque VACUUM et sature les connexions. Quel est le vrai problème ?","options":["La transaction reste « idle in transaction » pendant l'appel réseau externe : elle retient une connexion du pool ET un vieux snapshot qui empêche VACUUM de nettoyer les tuples morts ; il faut sortir l'appel externe de la transaction et ne tenir la transaction que le temps des requêtes DB","Le bug est l'ordre COMMIT après l'appel externe : PostgreSQL exige que tout appel réseau soit dans la transaction pour la cohérence ; déplacer l'appel après le COMMIT romprait l'atomicité applicative","Le problème est l'absence de `SET LOCAL statement_timeout` ; sans lui la requête `INSERT` s'exécute en boucle, ce qui explique la saturation, indépendamment de l'appel externe","La cause est que l'appel HTTP ouvre sa propre transaction imbriquée ; PostgreSQL ne supportant pas les transactions imbriquées, chaque appel externe crée un savepoint fantôme qui fuit"],"answer":0,"explanation":"Entre le premier `execute` et le `commit`, la transaction est ouverte et reste « idle in transaction » pendant les 2-5 s de l'appel HTTP externe. Deux dégâts : (1) elle monopolise une connexion du pool tout ce temps → sous charge le pool s'épuise ; (2) une transaction ouverte maintient un vieux xmin/snapshot, ce qui empêche VACUUM de recycler les tuples morts plus récents que ce snapshot → bloat et ralentissement globaux. Règle : ne JAMAIS faire d'I/O externe lente à l'intérieur d'une transaction DB ; garder les transactions courtes, faire l'appel externe hors transaction (ou via un pattern outbox pour la fiabilité). Les distracteurs 2/3/4 inventent des contraintes fausses (appel obligatoirement dans la tx, boucle d'INSERT, transactions imbriquées).","tags":["idle-in-transaction","vacuum","connection-pool","snapshot","python"]},
  {"id":"db-index-b-tree-sur-colonne-a-faible-cardin","type":"mcq","domain":"software","topic":"databases","difficulty":"senior","title":"Index B-tree sur colonne à faible cardinalité","company":"Markus Winand, « Use The Index, Luke », chap. sur la sélectivité","question":"Un développeur crée un index B-tree sur `sexe` (2 valeurs) pour accélérer `WHERE sexe = 'F'` sur une table où 50% des lignes sont 'F'. Pourquoi cet index est-il presque toujours inutile ici, mais pertinent dans un index composite ?","options":["Un prédicat renvoyant ~50% des lignes rend l'index scan plus cher que le seq scan (trop d'accès heap aléatoires) ; en revanche `sexe` peut être utile comme colonne de tête d'un index composite `(sexe, autre_colonne_sélective)` servant des requêtes combinées","Un index B-tree refuse les colonnes à moins de 3 valeurs distinctes ; PostgreSQL rejette donc silencieusement l'index sur `sexe`, ce qui explique son inefficacité, à moins de l'inclure dans un composite qui contourne la limite","L'index est inutile car les colonnes de type texte court ne sont jamais indexables seules ; il faut les combiner avec une colonne numérique dans un composite pour que le B-tree accepte de les trier","L'index sur `sexe` provoque un tri implicite de la table à chaque écriture, d'où la lenteur ; en composite ce tri est amorti sur plusieurs colonnes, ce qui le rend rentable pour une valeur à 50%"],"answer":0,"explanation":"Un index n'est avantageux que pour des prédicats SÉLECTIFS (peu de lignes retournées). Un prédicat sur `sexe = 'F'` qui matche ~50% de la table fait que l'index scan devrait sauter au heap pour la moitié des lignes (random I/O) : c'est plus coûteux qu'un seq scan séquentiel — l'optimiseur préférera d'ailleurs le seq scan. En revanche, une colonne peu sélective peut être UTILE comme colonne de tête d'un index COMPOSITE `(sexe, colonne_sélective)` : combinée à un second prédicat sélectif, elle restreint efficacement (et sert des requêtes filtrant sur les deux). Les distracteurs 2/3/4 inventent des règles inexistantes (rejet en dessous de 3 valeurs, texte non indexable seul, tri implicite à l'écriture).","tags":["cardinalité","sélectivité","index-composite","seq-scan","use-the-index-luke"]},
];
